import os
from pathlib import Path
from typing import Dict, Any
import tomli
import tomli_w


DEFAULT_CONFIG = {
    "storage": {
        "db_path": "~/.kb/kb.db"
    },
    "export": {
        "output_dir": "~/kb_exports",
        "html_theme": "light"
    }
}


class Config:
    def __init__(self, config_path: Path = None):
        self.config_path = config_path or self._get_default_config_path()
        self.config = self._load_config()

    def _get_default_config_path(self) -> Path:
        xdg_config = os.environ.get("XDG_CONFIG_HOME", "~/.config")
        config_dir = Path(xdg_config).expanduser() / "kb"
        config_dir.mkdir(parents=True, exist_ok=True)
        return config_dir / "config.toml"

    def _load_config(self) -> Dict[str, Any]:
        if not self.config_path.exists():
            return self._create_default_config()

        with open(self.config_path, "rb") as f:
            return tomli.load(f)

    def _create_default_config(self) -> Dict[str, Any]:
        with open(self.config_path, "wb") as f:
            tomli_w.dump(DEFAULT_CONFIG, f)
        return DEFAULT_CONFIG

    def get_db_path(self) -> Path:
        db_path = self.config.get("storage", {}).get("db_path", DEFAULT_CONFIG["storage"]["db_path"])
        return Path(db_path).expanduser()

    def get_export_dir(self) -> Path:
        export_dir = self.config.get("export", {}).get("output_dir", DEFAULT_CONFIG["export"]["output_dir"])
        path = Path(export_dir).expanduser()
        path.mkdir(parents=True, exist_ok=True)
        return path

    def get_html_theme(self) -> str:
        return self.config.get("export", {}).get("html_theme", DEFAULT_CONFIG["export"]["html_theme"])
