```python:storage.py
import sqlite3
from datetime import datetime
from typing import Optional, List, Tuple
from models import Note, Tag, Notebook
from config import Config


class SQLiteStorage:
    def __init__(self, config: Config):
        self.db_path = config.get_db_path()
        self.db_path.parent.mkdir(parents=True, exist_ok=True)
        self.conn = self._init_db()

    def _init_db(self) -> sqlite3.Connection:
        conn = sqlite3.connect(self.db_path)
        conn.execute("PRAGMA foreign_keys = ON")
        cursor = conn.cursor()

        # Create base tables
        cursor.execute("""
        CREATE TABLE IF NOT EXISTS notebooks (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT UNIQUE NOT NULL,
            description TEXT DEFAULT '',
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
        )
        """)

        cursor.execute("""
        CREATE TABLE IF NOT EXISTS tags (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT UNIQUE NOT NULL,
            color TEXT DEFAULT '#2563eb'
        )
        """)

        cursor.execute("""
        CREATE TABLE IF NOT EXISTS notes (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            title TEXT NOT NULL,
            content TEXT NOT NULL,
            created_at TIMESTAMP NOT NULL,
            updated_at TIMESTAMP NOT NULL,
            notebook_id INTEGER,
            FOREIGN KEY (notebook_id) REFERENCES notebooks (id)
        )
        """)

        cursor.execute("""
        CREATE TABLE IF NOT EXISTS note_tags (
            note_id INTEGER,
            tag_id INTEGER,
            PRIMARY KEY (note_id, tag_id),
            FOREIGN KEY (note_id) REFERENCES notes (id),
            FOREIGN KEY (tag_id) REFERENCES tags (id)
        )
        """)

        # Full-text search FTS5 table
        cursor.execute("""
        CREATE VIRTUAL TABLE IF NOT EXISTS notes_fts USING fts5(
            title, 
            content, 
            note_id UNINDEXED,
            content='notes'
        )
        """)

        conn.commit()
        return conn

    def add_note(self, note: Note) -> int:
        cursor = self.conn.cursor()
        cursor.execute("""
        INSERT INTO notes (title, content, created_at, updated_at, notebook_id)
        VALUES (?, ?, ?, ?, ?)
        """, (
            note.title,
            note.content,
            note.created_at,
            note.updated_at,
            note.notebook_id
        ))
        note_id = cursor.lastrowid

        # Add to FTS index
        cursor.execute("""
        INSERT INTO notes_fts (title, content, note_id)
        VALUES (?, ?, ?)
        """, (note.title, note.content, note_id))

        # Add tags
        if note.tags:
            for tag in note.tags:
                tag_id = self.get_or_create_tag(tag)
                cursor.execute("""
                INSERT OR IGNORE INTO note_tags (note_id, tag_id)
                VALUES (?, ?)
                """, (note_id, tag_id))

        self.conn.commit()
        return note_id

    def get_or_create_tag(self, tag: Tag) -> int:
        cursor = self.conn.cursor()
        cursor.execute("SELECT id, color FROM tags WHERE name = ?", (tag.name,))
        result = cursor.fetchone()
        if result:
            return result[0]

        cursor.execute("INSERT INTO tags (name, color) VALUES (?, ?)", (tag.name, tag.color))
        self.conn.commit()
        return cursor.lastrowid

    def get_note(self, note_id: int) -> Optional[Note]:
        cursor = self.conn.cursor()
        cursor.execute("""
        SELECT id, title, content, created_at, updated_at, notebook_id
        FROM notes WHERE id = ?
        """, (note_id,))
        result = cursor.fetchone()
        if not result:
            return None

        tags = self.get_tags_for_note(note_id)
        return Note(
            id=result[0],
            title=result[1],
            content=result[2],
            created_at=datetime.fromisoformat(result[3]),
            updated_at=datetime.fromisoformat(result[4]),
            notebook_id=result[5],
            tags=tags
        )

    def get_tags_for_note(self, note_id: int) -> List[Tag]:
        cursor = self.conn.cursor()
        cursor.execute("""
        SELECT t.id, t.name, t.color
        FROM tags t
        JOIN note_tags nt ON t.id = nt.tag_id
        WHERE nt.note_id = ?
        """, (note_id,))
        return [Tag(id=r[0], name=r[1], color=r[2]) for r in cursor.fetchall()]

    def list_all_notes(self) -> List[Note]:
        cursor = self.conn.cursor()
        cursor.execute("SELECT id, title, content, created_at, updated_at, notebook_id FROM notes ORDER BY updated_at DESC")
        notes = []
        for row in cursor.fetchall():
            tags = self.get_tags_for_note(row[0])
            notes.append(Note(
                id=row[0],
                title=row[1],
                content=row[2],
                created_at=datetime.fromisoformat(row[3]),
                updated_at=datetime.fromisoformat(row[4]),
                notebook_id=row[5],
                tags=tags
            ))
        return notes

    def fts_search(self, query: str) -> List[Tuple[int, float]]:
        cursor = self.conn.cursor()
        cursor.execute("""
        SELECT note_id, rank FROM notes_fts WHERE notes_fts MATCH ? ORDER BY rank
        """, (query,))
        return [(row[0], row[1]) for row in cursor.fetchall()]

    def delete_note(self, note_id: int) -> bool:
        cursor = self.conn.cursor()
        cursor.execute("DELETE FROM note_tags WHERE note_id = ?", (note_id,))
        cursor.execute("DELETE FROM notes_fts WHERE note_id = ?", (note_id,))
        cursor.execute("DELETE FROM notes WHERE id = ?", (note_id,))
        self.conn.commit()
        return cursor.rowcount > 0

    def add_tag_to_note(self, note_id: int, tag: Tag) -> bool:
        if not self.get_note(note_id):
            return False
        tag_id = self.get_or_create_tag(tag)
        cursor = self.conn.cursor()
        cursor.execute("INSERT OR IGNORE INTO note_tags (note_id, tag_id) VALUES (?, ?)", (note_id, tag_id))
        self.conn.commit()
        return True

    def remove_tag_from_note(self, note_id: int, tag_name: str) -> bool:
        cursor = self.conn.cursor()
        cursor.execute("SELECT id FROM tags WHERE name = ?", (tag_name,))
        result = cursor.fetchone()
        if not result:
            return False
        tag_id = result[0]
        cursor.execute("DELETE FROM note_tags WHERE note_id = ? AND tag_id = ?", (note_id, tag_id))
        self.conn.commit()
        return cursor.rowcount > 0

    def list_all_tags(self) -> List[Tag]:
        cursor = self.conn.cursor()
        cursor.execute("SELECT id, name, color FROM tags ORDER BY name")
        return [Tag(id=r[0], name=r[1], color=r[2]) for r in cursor.fetchall()]

    def get_notes_by_tag(self, tag_name: str) -> List[Note]:
        cursor = self.conn.cursor()
        cursor.execute("""
        SELECT n.id, n.title, n.content, n.created_at, n.updated_at, n.notebook_id
        FROM notes n
        JOIN note_tags nt ON n.id = nt.note_id
        JOIN tags t ON nt.tag_id = t.id
        WHERE t.name = ?
        ORDER BY n.updated_at DESC
        """, (tag_name,))
        notes = []
        for row in cursor.fetchall():
            tags = self.get_tags_for_note(row[0])
            notes.append(Note(
                id=row[0],
                title=row[1],
                content=row[2],
                created_at=datetime.fromisoformat(row[3]),
                updated_at=datetime.fromisoformat(row[4]),
                notebook_id=row[5],
                tags=tags
            ))
        return notes
