```python:search.py
from typing import List, Tuple
from models import Note
from storage import SQLiteStorage


class SearchEngine:
    def __init__(self, storage: SQLiteStorage):
        self.storage = storage

    def search(self, query: str, tag_filter: str = None, limit: int = 20) -> List[Tuple[Note, float]]:
        # Get base results from FTS
        fts_results = self.storage.fts_search(query)
        scored_results = []

        for note_id, fts_rank in fts_results:
            note = self.storage.get_note(note_id)
            if not note:
                continue

            # Apply relevance scoring
            score = self._calculate_score(note, query, fts_rank, tag_filter)
            if score is not None:
                scored_results.append((note, score))

        # Sort by descending score
        scored_results.sort(key=lambda x: -x[1])
        return scored_results[:limit]

    def _calculate_score(self, note: Note, query: str, fts_rank: float, tag_filter: str) -> float:
        # FTS rank is lower = better, invert to get base score
        base_score = 1 / (1 + fts_rank)

        # Boost score for query in title
        query_lower = query.lower()
        if query_lower in note.title.lower():
            base_score += 2.0

        # Boost for matching tags
        if note.tags:
            tag_names = [t.name.lower() for t in note.tags]
            if query_lower in tag_names:
                base_score += 1.0

            # Apply tag filter
            if tag_filter and tag_filter.lower() not in tag_names:
                return None

        return base_score

    def get_snippet(self, note: Note, query: str, max_length: int = 80) -> str:
        content = note.content.lower()
        query_lower = query.lower()
        pos = content.find(query_lower)

        if pos == -1:
            return note.content[:max_length] + ("..." if len(note.content) > max_length else "")

        start = max(0, pos - (max_length // 2))
        end = min(len(note.content), pos + (max_length // 2))
        snippet = note.content[start:end].strip()
        if start > 0:
            snippet = "..." + snippet
        if end < len(note.content):
            snippet += "..."
        return snippet
