```python:export.py
import json
from pathlib import Path
from typing import List, Optional
from models import Note
from config import Config


HTML_TEMPLATE = """
<!DOCTYPE html>
<html>
<head>
    <meta charset="UTF-8">
    <title>{title}</title>
    <style>
        :root {{
            --bg: {bg};
            --text: {text};
            --border: #e5e7eb;
        }}
        body {{
            max-width: 900px;
            margin: 0 auto;
            padding: 2rem;
            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, sans-serif;
            background-color: var(--bg);
            color: var(--text);
            line-height: 1.6;
        }}
        .note-meta {{
            color: #6b7280;
            font-size: 0.9rem;
            margin-bottom: 2rem;
            padding-bottom: 1rem;
            border-bottom: 1px solid var(--border);
        }}
        .tag {{
            display: inline-block;
            background-color: {tag_bg};
            color: white;
            padding: 0.2rem 0.6rem;
            border-radius: 12px;
            font-size: 0.8rem;
            margin-right: 0.5rem;
        }}
        h1 {{
            margin-bottom: 0.5rem;
        }}
        pre {{
            background-color: {pre_bg};
            padding: 1rem;
            border-radius: 8px;
            overflow-x: auto;
        }}
        img {{
            max-width: 100%;
            border-radius: 8px;
        }}
    </style>
</head>
<body>
    <h1>{title}</h1>
    <div class="note-meta">
        <div>Created: {created} | Updated: {updated}</div>
        <div style="margin-top: 0.5rem;">{tags}</div>
    </div>
    <div class="note-content">
        {content}
    </div>
</body>
</html>
"""


class Exporter:
    def __init__(self, config: Config):
        self.config = config
        self.output_dir = config.get_export_dir()

    def export_note(self, note: Note, format: str, output_path: Optional[Path] = None) -> Path:
        if not output_path:
            output_path = self.output_dir / f"{note.id}_{self._sanitize_filename(note.title)}.{format}"

        if format == "md":
            content = self._format_markdown(note)
        elif format == "json":
            content = json.dumps(note.to_dict(), indent=2)
        elif format == "html":
            content = self._format_html(note)
        else:
            raise ValueError(f"Unsupported format: {format}")

        output_path.parent.mkdir(parents=True, exist_ok=True)
        with open(output_path, "w", encoding="utf-8") as f:
            f.write(content)
        return output_path

    def export_all(self, notes: List[Note], format: str, output_dir: Optional[Path] = None) -> List[Path]:
        output_dir = output_dir or self.output_dir / f"all_notes_{format}"
        output_dir.mkdir(parents=True, exist_ok=True)
        exported = []
        for note in notes:
            path = output_dir / f"{note.id}_{self._sanitize_filename(note.title)}.{format}"
            exported.append(self.export_note(note, format, path))
        return exported

    def _sanitize_filename(self, filename: str) -> str:
        return "".join(c if c.isalnum() or c in "._- " else "_" for c in filename).strip().replace(" ", "_")

    def _format_markdown(self, note: Note) -> str:
        tags = ", ".join([f"`{t.name}`" for t in note.tags]) if note.tags else "None"
        return f"""# {note.title}

*Created: {note.created_at.strftime('%Y-%m-%d %H:%M')} | Updated: {note.updated_at.strftime('%Y-%m-%d %H:%M')}*
*Tags: {tags}*

---

{note.content}
"""

    def _format_html(self, note: Note) -> str:
        theme = self.config.get_html_theme()
        if theme == "dark":
            bg = "#111827"
            text = "#f9fafb"
            tag_bg = "#2563eb"
            pre_bg = "#1f2937"
        else:
            bg = "#ffffff"
            text = "#111827"
            tag_bg = "#2563eb"
            pre_bg = "#f3f4f6"

        tags_html = " ".join([f'<span class="tag" style="background-color: {t.color};">{t.name}</span>' for t in note.tags]) if note.tags else ""
        content = note.content.replace("\n", "<br>")
        # Simple markdown conversion for code blocks
        while "```" in content:
            content = content.replace("```", "<pre>", 1)
            content = content.replace("```", "</pre>", 1)

        return HTML_TEMPLATE.format(
            title=note.title,
            created=note.created_at.strftime('%Y-%m-%d %H:%M'),
            updated=note.updated_at.strftime('%Y-%m-%d %H:%M'),
            tags=tags_html,
            content=content,
            bg=bg,
            text=text,
            tag_bg=tag_bg,
            pre_bg=pre_bg
        )
