```python:cli.py
import click
from datetime import datetime
from typing import Optional
from config import Config
from storage import SQLiteStorage
from search import SearchEngine
from export import Exporter
from models import Note, Tag


# Initialize core services
config = Config()
storage = SQLiteStorage(config)
search_engine = SearchEngine(storage)
exporter = Exporter(config)


@click.group()
def cli():
    """Personal Knowledge Base CLI Manager"""
    pass


@cli.command()
@click.option("--title", prompt="Note title", help="Title of the note")
@click.option("--content", prompt="Note content", help="Content of the note", default=None)
@click.option("--tags", prompt="Comma-separated tags", help="Comma-separated list of tags", default="")
def add(title, content, tags):
    """Add a new note to the knowledge base"""
    if content is None:
        content = click.edit()
        if not content:
            click.echo("Error: No content provided, aborting")
            return

    tag_objs = []
    for tag_name in [t.strip() for t in tags.split(",") if t.strip()]:
        tag_objs.append(Tag(id=None, name=tag_name))

    now = datetime.now()
    note = Note(
        id=None,
        title=title,
        content=content,
        created_at=now,
        updated_at=now,
        tags=tag_objs
    )

    note_id = storage.add_note(note)
    click.echo(f"✅ Added new note with ID: {note_id}")


@cli.command()
@click.argument("query")
@click.option("--tag", "-t", help="Filter results by tag", default=None)
@click.option("--limit", "-l", help="Maximum number of results", default=20, type=int)
def search(query, tag, limit):
    """Search notes by keyword"""
    results = search_engine.search(query, tag_filter=tag, limit=limit)

    if not results:
        click.echo("No results found")
        return

    click.echo(f"Found {len(results)} results:\n")
    for i, (note, score) in enumerate(results, 1):
        snippet = search_engine.get_snippet(note, query)
        tags = ", ".join([t.name for t in note.tags]) if note.tags else "No tags"
        click.echo(click.style(f"[{i}] ID: {note.id} | Score: {score:.2f}", bold=True))
        click.echo(click.style(f"Title: {note.title}", fg="blue"))
        click.echo(f"Tags: {tags}")
        click.echo(f"Snippet: {snippet}\n")


@cli.command("list")
@click.option("--tag", "-t", help="Filter notes by tag", default=None)
def list_notes(tag):
    """List all notes, optionally filtered by tag"""
    if tag:
        notes = storage.get_notes_by_tag(tag)
    else:
        notes = storage.list_all_notes()

    if not notes:
        click.echo("No notes found")
        return

    click.echo(f"Total notes: {len(notes)}\n")
    for note in notes:
        tags = ", ".join([t.name for t in note.tags]) if note.tags else "No tags"
        click.echo(f"ID: {note.id} | Updated: {note.updated_at.strftime('%Y-%m-%d')}")
        click.echo(f"Title: {note.title} | Tags: {tags}\n")


@cli.command()
@click.argument("note_id", type=int)
@click.confirmation_option(prompt="Are you sure you want to delete this note?")
def delete(note_id):
    """Delete a note by ID"""
    success = storage.delete_note(note_id)
    if success:
        click.echo(f"✅ Deleted note {note_id}")
    else:
        click.echo(f"❌ Note {note_id} not found")


@cli.command()
@click.option("--id", "-i", help="ID of single note to export", default=None, type=int)
@click.option("--format", "-f", help="Export format (md/json/html)", default="md", type=click.Choice(["md", "json", "html"]))
@click.option("--output", "-o", help="Output path/directory", default=None, type=Path)
def export(id, format, output):
    """Export a single note or all notes"""
    if id:
        note = storage.get_note(id)
        if not note:
            click.echo(f"❌ Note {id} not found")
            return
        output_path = exporter.export_note(note, format, output)
        click.echo(f"✅ Exported note to {output_path}")
    else:
        notes = storage.list_all_notes()
        exported_paths = exporter.export_all(notes, format, output)
        click.echo(f"✅ Exported {len(exported_paths)} notes to {exported_paths[0].parent}")


@cli.group()
def tag():
    """Manage tags for notes"""
    pass


@tag.command("add")
@click.argument("note_id", type=int)
@click.argument("tag_name")
@click.option("--color", "-c", help="Tag color (hex code)", default="#2563eb")
def add_tag(note_id, tag_name, color):
    """Add a tag to a note"""
    success = storage.add_tag_to_note(note_id, Tag(id=None, name=tag_name, color=color))
    if success:
        click.echo(f"✅ Added tag '{tag_name}' to note {note_id}")
    else:
        click.echo(f"❌ Note {note_id} not found")


@tag.command("remove")
@click.argument("note_id", type=int)
@click.argument("tag_name")
def remove_tag(note_id, tag_name):
    """Remove a tag from a note"""
    success = storage.remove_tag_from_note(note_id, tag_name)
    if success:
        click.echo(f"✅ Removed tag '{tag_name}' from note {note_id}")
    else:
        click.echo(f"❌ Tag or note not found")


@tag.command("list")
def list_tags():
    """List all tags in the knowledge base"""
    tags = storage.list_all_tags()
    if not tags:
        click.echo("No tags found")
        return
    click.echo(f"Total tags: {len(tags)}\n")
    for tag in tags:
        click.echo(f"• {tag.name} (ID: {tag.id}, color: {tag.color})")


if __name__ == "__main__":
    cli()
