import abc
import logging
import os
import sys
import time
import importlib
from collections import defaultdict, deque
from dataclasses import dataclass, field
from typing import Dict, List, Optional, Callable, Any, Tuple

# Handle TOML imports for different Python versions
try:
    import tomllib
except ImportError:
    import tomli as tomllib

logger = logging.getLogger(__name__)


@dataclass
class PluginMetadata:
    """Track metadata for loaded plugins"""
    name: str
    version: str
    module: Any
    instance: Optional[Any] = None
    enabled: bool = False
    dependencies: List[Dict[str, str]] = field(default_factory=list)
    config: Dict[str, Any] = field(default_factory=dict)
    last_loaded: float = field(default_factory=lambda: time.time())


class EventBus:
    """Pub/sub event bus for inter-plugin communication"""
    def __init__(self):
        self._subscribers: Dict[str, List[Callable]] = defaultdict(list)

    def subscribe(self, event_name: str, callback: Callable) -> None:
        """Subscribe to an event"""
        self._subscribers[event_name].append(callback)

    def unsubscribe(self, event_name: str, callback: Callable) -> None:
        """Unsubscribe from an event"""
        if callback in self._subscribers[event_name]:
            self._subscribers[event_name].remove(callback)

    def dispatch(self, event_name: str, **data) -> None:
        """Dispatch an event to all subscribed callbacks"""
        for callback in self._subscribers.get(event_name, []):
            try:
                callback(**data)
            except Exception as e:
                logger.exception(f"Failed to dispatch event {event_name} to {callback}: {e}")


class Plugin(abc.ABC):
    """Abstract base class for all plugins"""
    # Override these in your plugin implementation
    NAME: str = ""
    VERSION: str = "0.0.1"
    # Dependencies format: [{"name": "plugin_name", "version": ">=1.0.0"}]
    DEPENDENCIES: List[Dict[str, str]] = []

    def __init__(self, manager: "PluginManager", config: Dict[str, Any]):
        self.manager = manager
        self.config = config
        self.logger = logging.getLogger(f"plugin.{self.NAME}")

    @abc.abstractmethod
    def on_load(self) -> None:
        """Called when plugin is first loaded"""
        pass

    @abc.abstractmethod
    def on_unload(self) -> None:
        """Called when plugin is being unloaded"""
        pass

    @abc.abstractmethod
    def on_enable(self) -> None:
        """Called when plugin is enabled"""
        pass

    @abc.abstractmethod
    def on_disable(self) -> None:
        """Called when plugin is being disabled"""
        pass

    def on_reload(self, old_instance: "Plugin") -> None:
        """Optional hook for state transfer during hot reload"""
        pass

    def send_event(self, event_name: str, **data) -> None:
        """Send an event via the global event bus"""
        self.manager.event_bus.dispatch(event_name, **data)

    def subscribe_event(self, event_name: str, callback: Callable) -> None:
        """Subscribe to an event from the global event bus"""
        self.manager.event_bus.subscribe(event_name, callback)

    def unsubscribe_event(self, event_name: str, callback: Callable) -> None:
        """Unsubscribe from an event"""
        self.manager.event_bus.unsubscribe(event_name, callback)


class PluginManager:
    """Main plugin manager that handles discovery, loading, and lifecycle"""
    def __init__(self, plugin_dir: str = "./plugins", config_dir: str = "./plugin_configs"):
        self.plugin_dir = os.path.abspath(plugin_dir)
        self.config_dir = os.path.abspath(config_dir)
        self.event_bus = EventBus()
        self.loaded_plugins: Dict[str, PluginMetadata] = {}
        self._discovered_plugins: List[Tuple[str, type, Any]] = []

        # Create required directories if they don't exist
        os.makedirs(self.plugin_dir, exist_ok=True)
        os.makedirs(self.config_dir, exist_ok=True)

        # Add plugin directory to Python path for imports
        if self.plugin_dir not in sys.path:
            sys.path.insert(0, self.plugin_dir)

    def _load_plugin_config(self, plugin_name: str) -> Dict[str, Any]:
        """Load TOML config for a plugin"""
        config_path = os.path.join(self.config_dir, f"{plugin_name}.toml")
        if not os.path.exists(config_path):
            return {}

        try:
            with open(config_path, "rb") as f:
                return tomllib.load(f)
        except Exception as e:
            logger.exception(f"Failed to load config for {plugin_name}: {e}")
            return {}

    def _check_version_compatibility(self, plugin_version: str, dep_version_spec: str) -> bool:
        """Validate if plugin version meets dependency requirements"""
        try:
            from packaging.version import parse
            from packaging.specifiers import SpecifierSet
            return parse(plugin_version) in SpecifierSet(dep_version_spec)
        except ImportError:
            logger.warning("packaging library not installed - skipping version checks")
            return True
        except Exception as e:
            logger.exception(f"Version check failed for {plugin_version} vs {dep_version_spec}: {e}")
            return False

    def _resolve_dependencies(self, plugin_meta: PluginMetadata) -> bool:
        """Resolve and load all required dependencies for a plugin"""
        for dep in plugin_meta.dependencies:
            dep_name = dep.get("name")
            dep_version = dep.get("version", ">=0.0.0")

            if not dep_name:
                logger.error(f"Invalid dependency for {plugin_meta.name}: missing name")
                return False

            # Load dependency if not already loaded
            if dep_name not in self.loaded_plugins:
                logger.info(f"Loading dependency {dep_name} for {plugin_meta.name}")
                if not self.load_plugin(dep_name):
                    logger.error(f"Failed to load dependency {dep_name}")
                    return False

            # Validate dependency version
            dep_plugin = self.loaded_plugins[dep_name]
            if not self._check_version_compatibility(dep_plugin.version, dep_version):
                logger.error(
                    f"{plugin_meta.name} requires {dep_name} {dep_version}, "
                    f"found version {dep_plugin.version}"
                )
                return False
        return True

    def discover_plugins(self) -> List[Tuple[str, type, Any]]:
        """Scan plugin directory and discover all valid plugin classes"""
        discovered = []
        for filename in os.listdir(self.plugin_dir):
            if not filename.endswith(".py") or filename.startswith("_"):
                continue

            module_name = filename[:-3]
            try:
                module = importlib.import_module(module_name)
                importlib.reload(module)

                # Find Plugin subclasses in the module
                for attr_name in dir(module):
                    attr = getattr(module, attr_name)
                    if (isinstance(attr, type) 
                        and issubclass(attr, Plugin) 
                        and attr != Plugin):

                        if not attr.NAME:
                            logger.warning(f"Skipping {attr_name} in {filename}: no NAME set")
                            continue
                        discovered.append((attr.NAME, attr, module))
            except Exception as e:
                logger.exception(f"Failed to import plugin module {filename}: {e}")
        return discovered

    def load_plugin(self, plugin_name: str) -> bool:
        """Load a single plugin by name"""
        # Discover plugins if not already done
        if not self._discovered_plugins:
            self._discovered_plugins = self.discover_plugins()

        # Find target plugin class and module
        plugin_class = None
        plugin_module = None
        for name, cls, mod in self._discovered_plugins:
            if name == plugin_name:
                plugin_class = cls
                plugin_module = mod
                break

        if not plugin_class:
            logger.error(f"Plugin {plugin_name} not found")
            return False

        if plugin_name in self.loaded_plugins:
            logger.warning(f"Plugin {plugin_name} already loaded")
            return True

        # Load plugin config
        config = self._load_plugin_config(plugin_name)

        # Create plugin instance
        try:
            instance = plugin_class(self, config.get("config", {}))
        except Exception as e:
            logger.exception(f"Failed to create instance for {plugin_name}: {e}")
            return False

        # Create plugin metadata
        meta = PluginMetadata(
            name=plugin_name,
            version=plugin_class.VERSION,
            module=plugin_module,
            instance=instance,
            dependencies=plugin_class.DEPENDENCIES,
            config=config
        )

        # Resolve dependencies
        if not self._resolve_dependencies(meta):
            return False

        # Run on_load hook
        try:
            instance.on_load()
        except Exception as e:
            logger.exception(f"on_load hook failed for {plugin_name}: {e}")
            return False

        self.loaded_plugins[plugin_name] = meta
        logger.info(f"Loaded plugin {plugin_name} v{plugin_class.VERSION}")
        return True

    def enable_plugin(self, plugin_name: str) -> bool:
        """Enable a loaded plugin"""
        if plugin_name not in self.loaded_plugins:
            logger.error(f"Plugin {plugin_name} not loaded")
            return False

        meta = self.loaded_plugins[plugin_name]
        if meta.enabled:
            logger.warning(f"Plugin {plugin_name} already enabled")
            return True

        try:
            meta.instance.on_enable()
            meta.enabled = True
            logger.info(f"Enabled plugin {plugin_name}")
            return True
        except Exception as e:
            logger.exception(f"on_enable hook failed for {plugin_name}: {e}")
            return False

    def disable_plugin(self, plugin_name: str) -> bool:
        """Disable a loaded plugin"""
        if plugin_name not in self.loaded_plugins:
            logger.error(f"Plugin {plugin_name} not loaded")
            return False

        meta = self.loaded_plugins[plugin_name]
        if not meta.enabled:
            logger.warning(f"Plugin {plugin_name} already disabled")
            return True

        try:
            meta.instance.on_disable()
            meta.enabled = False
            logger.info(f"Disabled plugin {plugin_name}")
            return True
        except Exception as e:
            logger.exception(f"on_disable hook failed for {plugin_name}: {e}")
            return False

    def unload_plugin(self, plugin_name: str, recursive: bool = True) -> bool:
        """Unload a plugin, optionally unload dependent plugins recursively"""
        if plugin_name not in self.loaded_plugins:
            logger.error(f"Plugin {plugin_name} not loaded")
            return False

        meta = self.loaded_plugins[plugin_name]

        # Disable first if enabled
        if meta.enabled:
            self.disable_plugin(plugin_name)

        # Run on_unload hook
        try:
            meta.instance.on_unload()
        except Exception as e:
            logger.exception(f"on_unload hook failed for {plugin_name}: {e}")

        # Unload dependent plugins
        if recursive:
            dependent_plugins = [
                name for name, dep_meta in self.loaded_plugins.items()
                if any(dep.get("name") == plugin_name for dep in dep_meta.dependencies)
            ]
            for dep_name in dependent_plugins:
                self.unload_plugin(dep_name, recursive=True)

        # Remove from registry and unload module
        del self.loaded_plugins[plugin_name]
        try:
            module_name = meta.module.__name__
            if module_name in sys.modules:
                del sys.modules[module_name]
        except Exception as e:
            logger.exception(f"Failed to unload module for {plugin_name}: {e}")

        logger.info(f"Unloaded plugin {plugin_name}")
        return True

    def reload_plugin(self, plugin_name: str) -> bool:
        """Hot-reload a plugin at runtime"""
        if plugin_name not in self.loaded_plugins:
            logger.error(f"Plugin {plugin_name} not loaded")
            return False

        old_meta = self.loaded_plugins[plugin_name]
        old_instance = old_meta.instance
        was_enabled = old_meta.enabled

        # Unload without recursive to avoid breaking dependencies
        self.unload_plugin(plugin_name, recursive=False)

        try:
            # Reload the module
            module = importlib.reload(old_meta.module)

            # Find updated plugin class
            new_plugin_class = None
            for attr_name in dir(module):
                attr = getattr(module, attr_name)
                if isinstance(attr, type) and issubclass(attr, Plugin) and attr != Plugin:
                    if attr.NAME == plugin_name:
                        new_plugin_class = attr
                        break

            if not new_plugin_class:
                logger.error(f"Updated plugin class not found for {plugin_name}")
                return False

            # Load new instance and config
            config = self._load_plugin_config(plugin_name)
            new_instance = new_plugin_class(self, config.get("config", {}))

            # Transfer state via on_reload hook
            if hasattr(new_instance, "on_reload"):
                try:
                    new_instance.on_reload(old_instance)
                except Exception as e:
                    logger.exception(f"on_reload hook failed for {plugin_name}: {e}")

            # Create new metadata
            new_meta = PluginMetadata(
                name=plugin_name,
                version=new_plugin_class.VERSION,
                module=module,
                instance=new_instance,
                dependencies=new_plugin_class.DEPENDENCIES,
                config=config
            )

            # Resolve dependencies
            if not self._resolve_dependencies(new_meta):
                return False

            # Run on_load hook
            try:
                new_instance.on_load()
            except Exception as e:
                logger.exception(f"on_load hook failed for reloaded {plugin_name}: {e}")
                return False

            # Re-enable if was enabled before
            if was_enabled:
                try:
                    new_instance.on_enable()
                    new_meta.enabled = True
                except Exception as e:
                    logger.exception(f"on_enable hook failed for reloaded {plugin_name}: {e}")
                    return False

            self.loaded_plugins[plugin_name] = new_meta
            logger.info(f"Successfully reloaded plugin {plugin_name}")
            return True
        except Exception as e:
            logger.exception(f"Failed to reload {plugin_name}: {e}")
            return False

    def load_all_plugins(self) -> None:
