## 1. Domain Model & Exceptions

```python
# domain.py
from __future__ import annotations
from dataclasses import dataclass


@dataclass
class User:
    id: int
    name: str
    email: str
    role: str
    active: bool = True


# exceptions.py
class UserServiceError(Exception):
    """Base exception for any error raised by the user-service stack."""


class ValidationError(UserServiceError):
    """Raised when input fails validation."""


class InvalidEmailError(ValidationError):
    """Raised when an email is malformed."""


class InvalidRoleError(ValidationError):
    """Raised when a role is not in the allowed set."""


class InvalidNameError(ValidationError):
    """Raised when a name is empty/whitespace."""


class RepositoryError(UserServiceError):
    """Raised when persistence operations fail."""


class UserNotFoundError(RepositoryError):
    """Raised when a user lookup returns nothing."""


class EmailServiceError(UserServiceError):
    """Raised when email delivery fails."""
