## 3. UserRepository — persistence responsibility

```python
# repository.py
from __future__ import annotations
from typing import Optional, Iterable

from domain import User
from db import DatabaseConnection
from exceptions import RepositoryError, UserNotFoundError


class UserRepository:
    """Owns in-memory + DB persistence of User aggregates."""

    def __init__(self, db_conn: Optional[DatabaseConnection] = None) -> None:
        self._users: list[User] = []
        self._db_conn = db_conn
        self._next_id = 1

    # ----- ID generation -----
    def next_id(self) -> int:
        current = self._next_id
        self._next_id += 1
        return current

    # ----- Reads -----
    def find_by_id(self, user_id: int) -> Optional[User]:
        return next((u for u in self._users if u.id == user_id), None)

    def list_all(self) -> Iterable[User]:
        return tuple(self._users)

    # ----- Writes -----
    def add(self, user: User) -> User:
        if self._db_conn is not None:
            try:
                self._db_conn.execute(
                    "INSERT INTO users (id, name, email, role) VALUES (?, ?, ?, ?)",
                    (user.id, user.name, user.email, user.role),
                )
            except Exception as exc:  # noqa: BLE001
                raise RepositoryError(f"Failed to insert user {user.id}") from exc
        self._users.append(user)
        return user

    def deactivate(self, user_id: int) -> User:
        user = self.find_by_id(user_id)
        if user is None:
            raise UserNotFoundError(f"User id={user_id} not found")
        user.active = False
        if self._db_conn is not None:
            try:
                self._db_conn.execute(
                    "UPDATE users SET active=0 WHERE id=?",
                    (user_id,),
                )
            except Exception as exc:  # noqa: BLE001
                raise RepositoryError(f"Failed to deactivate user {user_id}") from exc
        return user
