# email_service.py
from __future__ import annotations

from exceptions import EmailServiceError


class EmailService:
    """Queues outbound emails and dispatches them."""

    def __init__(self) -> None:
        self._queue: list[dict[str, str]] = []

    def enqueue(self, to: str, subject: str, body: str) -> None:
        if not to or "@" not in to:
            raise EmailServiceError(f"Refusing to enqueue email with bad recipient: {to!r}")
        if not subject:
            raise EmailServiceError("Subject is required")
        self._queue.append({"to": to, "subject": subject, "body": body})

    def send_all(self) -> int:
        sent = 0
        failures: list[str] = []
        for item in list(self._queue):
            try:
                self._deliver(item)
                self._queue.remove(item)
                sent += 1
            except Exception as exc:  # noqa: BLE001
                failures.append(f"{item['to']}: {exc}")
        if failures:
            raise EmailServiceError("Some emails failed: " + "; ".join(failures))
        return sent

    def pending_count(self) -> int:
        return len(self._queue)

    # ----- internal -----
    @staticmethod
    def _deliver(email: dict[str, str]) -> None:
        # In production: open SMTP/SES client. Here we just print.
        print(f"Sending to {email['to']}: {email['subject']}")
