# validator.py
from __future__ import annotations

from exceptions import InvalidEmailError, InvalidNameError, InvalidRoleError, ValidationError


class UserValidator:
    """Pure, stateless validation rules for user-related inputs."""

    VALID_ROLES: frozenset[str] = frozenset({"admin", "user", "guest"})

    @classmethod
    def validate_name(cls, name: str) -> None:
        if not isinstance(name, str) or not name.strip():
            raise InvalidNameError("Name must be a non-empty string")

    @classmethod
    def validate_email(cls, email: str) -> None:
        if not isinstance(email, str) or "@" not in email or email.startswith("@") or email.endswith("@"):
            raise InvalidEmailError(f"Invalid email: {email!r}")

    @classmethod
    def validate_role(cls, role: str) -> None:
        if role not in cls.VALID_ROLES:
            raise InvalidRoleError(
                f"Invalid role: {role!r}. Must be one of {sorted(cls.VALID_ROLES)}"
            )

    @classmethod
    def validate_all(cls, name: str, email: str, role: str) -> None:
        cls.validate_name(name)
        cls.validate_email(email)
        cls.validate_role(role)
