## 7. UserService — facade that coordinates

```python
# service.py
from __future__ import annotations
from typing import Optional

from domain import User
from repository import UserRepository
from email_service import EmailService
from audit_service import AuditService
from validator import UserValidator
from db import DatabaseConnection
from exceptions import UserNotFoundError


class UserService:
    """Facade coordinating repository, email, audit, and validator."""

    def __init__(
        self,
        repository: UserRepository,
        email_service: EmailService,
        audit_service: AuditService,
        validator: type[UserValidator] = UserValidator,
    ) -> None:
        self._repo = repository
        self._email = email_service
        self._audit = audit_service
        self._validator = validator

    # ----- factory helper -----
    @classmethod
    def with_defaults(cls, db_conn: Optional[DatabaseConnection] = None) -> "UserService":
        return cls(
            repository=UserRepository(db_conn=db_conn),
            email_service=EmailService(),
            audit_service=AuditService(),
        )

    # ----- public API -----
    def create_user(self, name: str, email: str, role: str) -> User:
        self._validator.validate_all(name, email, role)

        user = User(
            id=self._repo.next_id(),
            name=name,
            email=email,
            role=role,
            active=True,
        )
        self._repo.add(user)
        self._email.enqueue(email, "Welcome", f"Hi {name}")
        self._audit.log(f"User {name} created with role {role}")
        return user

    def delete_user(self, user_id: int) -> bool:
        user = self._repo.find_by_id(user_id)
        if user is None:
            return False
        self._repo.deactivate(user.id)
        self._email.enqueue(
            user.email,
            "Account Deleted",
            "Your account has been deleted",
        )
        self._audit.log(f"User {user.name} deleted")
        return True

    def get_user(self, user_id: int) -> User:
        user = self._repo.find_by_id(user_id)
        if user is None:
            raise UserNotFoundError(f"User id={user_id} not found")
        return user

    def send_emails(self) -> int:
        return self._email.send_all()

    def get_audit_log(self) -> list[str]:
        return self._audit.get_log()
