```python
"""
Plugin Architecture System
Supports: lifecycle hooks, discovery, hot-reload, dependencies, isolation,
configuration via TOML, version compatibility, and an event bus.
"""

import importlib
import importlib.util
import inspect
import logging
import os
import sys
import threading
from collections import defaultdict
from pathlib import Path
from typing import Any, Callable, Dict, List, Optional, Set, Type

# ----------------------------------------------------------------------
# Version handling (simple semantic versioning)
# ----------------------------------------------------------------------
class Version:
    """Simple version class for comparison (e.g., '1.2.3')."""
    def __init__(self, version_str: str):
        self._parts = tuple(int(x) for x in version_str.split('.'))
        self._str = version_str

    def __str__(self):
        return self._str

    def __repr__(self):
        return f"Version('{self._str}')"

    def __eq__(self, other):
        if isinstance(other, Version):
            return self._parts == other._parts
        return NotImplemented

    def __lt__(self, other):
        if isinstance(other, Version):
            return self._parts < other._parts
        return NotImplemented

    def __le__(self, other):
        return self == other or self < other

    def __gt__(self, other):
        if isinstance(other, Version):
            return self._parts > other._parts
        return NotImplemented

    def __ge__(self, other):
        return self == other or self > other

    def __hash__(self):
        return hash(self._parts)

    @staticmethod
    def parse(version_str: str) -> 'Version':
        return Version(version_str)


# ----------------------------------------------------------------------
# Configuration loading (TOML)
# ----------------------------------------------------------------------
try:
    import tomllib  # Python 3.11+
except ImportError:
    try:
        import tomli as tomllib
    except ImportError:
        tomllib = None

class PluginConfig:
    """Loads and provides plugin configuration from a TOML file."""
    def __init__(self, config_path: Optional[Path] = None):
        self._data: Dict[str, Any] = {}
        if config_path and config_path.exists():
            self._load(config_path)

    def _load(self, path: Path):
        if tomllib is None:
            raise RuntimeError("TOML parser not available. Install tomli or use Python 3.11+")
        with open(path, 'rb') as f:
            self._data = tomllib.load(f)

    def get(self, key: str, default: Any = None) -> Any:
        return self._data.get(key, default)

    def __getitem__(self, key: str) -> Any:
        return self._data[key]

    def __contains__(self, key: str) -> bool:
        return key in self._data

    def as_dict(self) -> Dict[str, Any]:
        return self._data.copy()


# ----------------------------------------------------------------------
# Event Bus
# ----------------------------------------------------------------------
class EventBus:
    """Simple publish/subscribe event bus for inter-plugin communication."""
    def __init__(self):
        self._subscribers: Dict[str, List[Callable]] = defaultdict(list)
        self._lock = threading.Lock()

    def subscribe(self, event: str, callback: Callable):
        """Register a callback for an event."""
        with self._lock:
            self._subscribers[event].append(callback)

    def unsubscribe(self, event: str, callback: Callable):
        """Remove a callback from an event."""
        with self._lock:
            try:
                self._subscribers[event].remove(callback)
                if not self._subscribers[event]:
                    del self._subscribers[event]
            except ValueError:
                pass

    def publish(self, event: str, **kwargs):
        """Publish an event, calling all subscribers with the given keyword arguments."""
        with self._lock:
            callbacks = list(self._subscribers.get(event, []))
        for cb in callbacks:
            try:
                cb(**kwargs)
            except Exception as e:
                logging.error(f"EventBus: Error in subscriber for event '{event}': {e}")

    def clear(self):
        """Remove all subscribers."""
        with self._lock:
            self._subscribers.clear()


# ----------------------------------------------------------------------
# Plugin Base Class
# ----------------------------------------------------------------------
class PluginBase:
    """
    Base class for all plugins.
    Subclasses must set at least the `name` and `version` class attributes.
    """
    # Required metadata
    name: str = ""
    version: str = "0.0.0"
    # Optional: list of plugin names this plugin depends on
    requires: List[str] = []
    # Optional: version requirements for dependencies (dict: plugin_name -> version spec)
    # e.g., {"plugin_b": ">=1.0,<2.0"}
    dependency_versions: Dict[str, str] = {}

    def __init__(self, config: Optional[PluginConfig] = None):
        self.config = config or PluginConfig()
        self._enabled = False
        self._loaded = False

    # Lifecycle hooks
    def on_load(self, event_bus: EventBus):
        """Called when the plugin is loaded. Use to subscribe to events, etc."""
        pass

    def on_unload(self):
        """Called when the plugin is unloaded. Clean up resources."""
        pass

    def on_enable(self):
        """Called when the plugin is enabled (after loading)."""
        pass

    def on_disable(self):
        """Called when the plugin is disabled."""
        pass

    @property
    def is_enabled(self) -> bool:
        return self._enabled

    @property
    def is_loaded(self) -> bool:
        return self._loaded


# ----------------------------------------------------------------------
# Plugin Manager
# ----------------------------------------------------------------------
class PluginManager:
    """
    Manages the lifecycle of plugins: discovery, loading, enabling, disabling,
    hot-reloading, dependency resolution, and isolation.
    """
    def __init__(self, plugin_dirs: List[Path], event_bus: Optional[EventBus] = None):
        self._plugin_dirs = [Path(d) for d in plugin_dirs]
        self._event_bus = event_bus or EventBus()
        self._plugins: Dict[str, PluginBase] = {}          # name -> instance
        self._plugin_classes: Dict[str, Type[PluginBase]] = {}  # name -> class (for reload)
        self._plugin_modules: Dict[str, Any] = {}          # name -> module
        self._plugin_configs: Dict[str, PluginConfig] = {} # name -> config
        self._enabled_plugins: Set[str] = set()
        self._lock = threading.Lock()
        self._logger = logging.getLogger(__name__)

    # ------------------------------------------------------------------
    # Discovery
    # ------------------------------------------------------------------
    def discover_plugins(self) -> List[str]:
        """
        Scan plugin directories for valid plugins.
        Returns a list of discovered plugin names.
        """
        discovered = []
        for plugin_dir in self._plugin_dirs:
            if not plugin_dir.is_dir():
                continue
            for entry in plugin_dir.iterdir():
                if entry.is_dir() and not entry.name.startswith('_'):
                    plugin_name = entry.name
                    if self._is_valid_plugin_dir(entry):
                        discovered.append(plugin_name)
        return discovered

    def _is_valid_plugin_dir(self, dir_path: Path) -> bool:
        """Check if a directory contains a valid plugin module."""
        # Look for plugin.py or __init__.py
        plugin_file = dir_path / 'plugin.py'
        init_file = dir_path / '__init__.py'
        return plugin_file.exists() or init_file.exists()

    # ------------------------------------------------------------------
    # Loading
    # ------------------------------------------------------------------
    def load_plugin(self, plugin_name: str) -> bool:
        """
        Load a plugin by name. Discovers it if not already known.
        Returns True on success, False on failure.
        """
        with self._lock:
            if plugin_name in self._plugins:
                self._logger.warning(f"Plugin '{plugin_name}' already loaded.")
                return True

            # Find the plugin directory
            plugin_dir = self._find_plugin_dir(plugin_name)
            if not plugin_dir:
                self._logger.error(f"Plugin '{plugin_name}' not found in any plugin directory.")
                return False

            # Load configuration
            config = self._load_config(plugin_dir)

            # Import the plugin module
            module, plugin_class = self._import_plugin_module(plugin_name, plugin_dir)
            if module is None or plugin_class is None:
                return False

            # Check version compatibility of the plugin itself (if needed)
            # For now, we trust the plugin's version string.

            # Create instance
            try:
                plugin_instance = plugin_class(config=config)
            except Exception as e:
                self._logger.error(f"Failed to instantiate plugin '{plugin_name}': {e}")
                return False

            # Store metadata
            self._plugin_classes[plugin_name] = plugin_class
            self._plugin_modules[plugin_name] = module
            self._plugin_configs[plugin_name] = config
            self._plugins[plugin_name] = plugin_instance

            # Mark as loaded (but not yet enabled)
            plugin_instance._loaded = True

            self._logger.info(f"Plugin '{plugin_name}' loaded (version {plugin_instance.version}).")
            return True

    def _find_plugin_dir(self, plugin_name: str) -> Optional[Path]:
        for d in self._plugin_dirs:
            candidate = d / plugin_name
            if candidate.is_dir() and self._is_valid_plugin_dir(candidate):
                return candidate
        return None

    def _load_config(self, plugin_dir: Path) -> PluginConfig:
        config_path = plugin_dir / 'config.toml'
        return PluginConfig(config_path)

    def _import_plugin_module(self, plugin_name: str, plugin_dir: Path):
        """
        Import the plugin module and find the PluginBase subclass.
        Returns (module, plugin_class) or (None, None) on failure.
        """
        # Determine the module file
        plugin_file = plugin_dir / 'plugin.py'
        init_file = plugin_dir / '__init__.py'
        if plugin_file.exists():
            module_path = str(plugin_file)
            module_name = f"plugins.{plugin_name}.plugin"
        elif init_file.exists():
            module_path = str(init_file)
            module_name = f"plugins.{plugin_name}"
        else:
            self._logger.error(f"No plugin module found in '{plugin_dir}'.")
            return None, None

        # Add plugin directory to sys.path temporarily if needed
        parent_dir = str(plugin_dir.parent)
        if parent_dir not in sys.path:
            sys.path.insert(0, parent_dir)

        try:
            spec = importlib.util.spec_from_file_location(module_name, module_path)
            if spec is None:
                self._logger.error(f"Could not create spec for '{module_name}'.")
                return None, None
            module = importlib.util.module_from_spec(spec)
            spec.loader.exec_module(module)
        except Exception as e:
            self._logger.error(f"Failed to import plugin module '{module_name}': {e}")
            return None, None
        finally:
            # Remove the temporary path (optional, but good practice)
            if parent_dir in sys.path:
                sys.path.remove(parent_dir)

        # Find the PluginBase subclass in the module
        plugin_class = None
        for name, obj in inspect.getmembers(module, inspect.isclass):
            if issubclass(obj, PluginBase) and obj is not PluginBase:
                plugin_class = obj
                break
        if plugin_class is None:
            self._logger.error(f"No PluginBase subclass found in module '{module_name}'.")
            return None, None

        # Ensure the class has a name
        if not plugin_class.name:
            plugin_class.name = plugin_name
        return module, plugin_class

    # ------------------------------------------------------------------
    # Unloading
    # ------------------------------------------------------------------
    def unload_plugin(self, plugin_name: str) -> bool:
        """Unload a plugin (disable first if enabled)."""
        with self._lock:
            if plugin_name not in self._plugins:
                self._logger.warning(f"Plugin '{plugin_name}' not loaded.")
                return False

            # Disable if enabled
            if plugin_name in self._enabled_plugins:
                self.disable_plugin(plugin_name)

            plugin = self._plugins[plugin_name]
            try:
                plugin.on_unload()
            except Exception as e:
                self._logger.error(f"Error in on_unload of '{plugin_name}': {e}")

            # Clean up
            plugin._loaded = False
            del self._plugins[plugin_name]
            del self._plugin_classes[plugin_name]
            del self._plugin_modules[plugin_name]
            del self._plugin_configs[plugin_name]

            self._logger.info(f"Plugin '{plugin_name}' unloaded.")
            return True

    # ------------------------------------------------------------------
    # Enabling / Disabling
    # ------------------------------------------------------------------
    def enable_plugin(self, plugin_name: str) -> bool:
        """
        Enable a plugin. Loads it first if not loaded.
        Also enables all dependencies (recursively).
        """
        with self._lock:
            if plugin_name not in self._plugins:
                if not self.load_plugin(plugin_name):
                    return False

            plugin = self._plugins[plugin_name]
            if plugin.is_enabled:
                self._logger.debug(f"Plugin '{plugin_name}' already enabled.")
                return True

            # Check and enable dependencies
            if not self._resolve_dependencies(plugin_name):
                return False

            try:
                plugin.on_enable()
            except Exception as e:
                self._logger.error(f"Error in on_enable of '{plugin_name}': {e}")
                return False

            plugin._enabled = True
            self._enabled_plugins.add(plugin_name)
            self._logger.info(f"Plugin '{plugin_name}' enabled.")
            return True

    def disable_plugin(self, plugin_name: str) -> bool:
        """Disable a plugin. Also disables plugins that depend on it."""
        with self._lock:
            if plugin_name not in self._plugins:
                self._logger.warning(f"Plugin '{plugin_name}' not loaded.")
                return False

            plugin = self._plugins[plugin_name]
            if not plugin.is_enabled:
                return True

            # Find reverse dependencies (plugins that require this one)
            reverse_deps = self._find_reverse_dependencies(plugin_name)
            for dep_name in reverse_deps:
                if dep_name in self._enabled_plugins:
                    self.disable_plugin(dep_name)

            try:
                plugin.on_disable()
            except Exception as e:
                self._logger.error(f"Error in on_disable of '{plugin_name}': {e}")

            plugin._enabled = False
            self._enabled_plugins.discard(plugin_name)
            self._logger.info(f"Plugin '{plugin_name}' disabled.")
            return True

    def _resolve_dependencies(self, plugin_name: str) -> bool:
        """
        Ensure all dependencies of plugin_name are loaded and enabled.
        Returns True if all dependencies satisfied, False otherwise.
        """
        plugin = self._plugins[plugin_name]
        for dep_name in plugin.requires:
            if dep_name not in self._plugins:
                # Try to load the dependency
                if not self.load_plugin(dep_name):
                    self._logger.error(f"Dependency '{dep_name}' for '{plugin_name}' could not be loaded.")
                    return False
            # Check version compatibility
            dep_plugin = self._plugins[dep_name]
            if not self._check_version_compatibility(plugin_name, dep_name):
                return False
            # Enable dependency if not already enabled
            if dep_name not in self._enabled_plugins:
                if not self.enable_plugin(dep_name):
                    self._logger.error(f"Failed to enable dependency '{dep_name}' for '{plugin_name}'.")
                    return False
        return True

    def _check_version_compatibility(self, plugin_name: str, dep_name: str) -> bool:
        """Check if the version of dep_name satisfies the requirements of plugin_name."""
        plugin = self._plugins[plugin_name]
        dep_plugin = self._plugins[dep_name]
        if dep_name in plugin.dependency_versions:
            required_version_str = plugin.dependency_versions[dep_name]
            # Simple version range parsing (e.g., ">=1.0,<2.0")
            # For production, use a library like packaging.specifiers.
            # Here we implement a minimal check.
            if not self._simple_version_match(dep_plugin.version, required_version_str):
                self._logger.error(
                    f"Version mismatch: '{plugin_name}' requires '{dep_name}' version "
                    f"'{required_version_str}', but '{dep_name}' is version '{dep_plugin.version}'."
                )
                return False
        return True

    def _simple_version_match(self, version_str: str, spec: str) -> bool:
        """
        Very simple version spec parser. Supports:
        - ">=1.0"
        - ">=1.0,<2.0"
        - "==1.0"
        - ">1.0"
        - "<1.0"
        - "<=1.0"
        - "*" (any)
        """
        version = Version(version_str)
        clauses = [s.strip() for s in spec.split(',')]
        for clause in clauses:
            if clause == '*':
                continue
            if clause.startswith('>='):
                op = '>='
                target = clause[2:]
            elif clause.startswith('<='):
                op = '<='
                target = clause[2:]
            elif clause.startswith('=='):
                op = '=='
                target = clause[2:]
            elif clause.startswith('>'):
                op = '>'
                target = clause[1:]
            elif clause.startswith('<'):
                op = '<'
                target = clause[1:]
            else:
                # Assume exact match
                op = '=='
                target = clause
            target_version = Version(target)
            if op == '>=' and not (version >= target_version):
                return False
            elif op == '<=' and not (version <= target_version):
                return False
            elif op == '==' and not (version == target_version):
                return False
            elif op == '>' and not (version > target_version):
                return False
            elif op == '<' and not (version < target_version):
                return False
        return True

    def _find_reverse_dependencies(self, plugin_name: str) -> List[str]:
        """Return list of plugin names that depend on plugin_name."""
        reverse = []
        for name, plugin in self._plugins.items():
            if plugin_name in plugin.requires:
                reverse.append(name)
        return reverse

    # ------------------------------------------------------------------
    # Hot-Reload
    # ------------------------------------------------------------------
    def reload_plugin(self, plugin_name: str) -> bool:
        """
        Hot-reload a plugin: unload the current instance, reload the module,
        and load the new instance. The plugin will be re-enabled if it was enabled.
        """
        with self._lock:
            if plugin_name not in self._plugins:
                self._logger.warning(f"Plugin '{plugin_name}' not loaded, cannot reload.")
                return False

            was_enabled = plugin_name in self._enabled_plugins

            # Unload (disable if enabled, then unload)
            if not self.unload_plugin(plugin_name):
                return False

            # Reload the module (if we still have the old module reference)
            if plugin_name in self._plugin_modules:
                try:
                    importlib.reload(self._plugin_modules[plugin_name])
                except Exception as e:
                    self._logger.error(f"Failed to reload module for '{plugin_name}': {e}")
                    return False

            # Load the new version
            if not self.load_plugin(plugin_name):
                return False

            # Re-enable if it was enabled
            if was_enabled:
                if not self.enable_plugin(plugin_name):
                    self._logger.error(f"Failed to re-enable plugin '{plugin_name}' after reload.")
                    return False

            self._logger.info(f"Plugin '{plugin_name}' hot-reloaded successfully.")
            return True

    # ------------------------------------------------------------------
    # Utility
    # ------------------------------------------------------------------
    def get_plugin(self, plugin_name: str) -> Optional[PluginBase]:
        return self._plugins.get(plugin_name)

    def list_plugins(self) -> List[str]:
        return list(self._plugins.keys())

    def list_enabled_plugins(self) -> List[str]:
        return list(self._enabled_plugins)

    def get_event_bus(self) -> EventBus:
        return self._event_bus

    def shutdown(self):
        """Gracefully shut down all plugins."""
        with self._lock:
            for name in list(self._enabled_plugins):
                self.disable_plugin(name)
            for name in list(self._plugins.keys()):
                self.unload_plugin(name)
            self._event_bus.clear()
            self._logger.info("Plugin manager shut down.")


# ----------------------------------------------------------------------
# Example usage (if run as script)
# ----------------------------------------------------------------------
if __name__ == "__main__":
    logging.basicConfig(level=logging.INFO)

    # Create a temporary directory structure for demonstration
    import tempfile
    import shutil

    tmpdir = Path(tempfile.mkdtemp())
    plugin_dir = tmpdir / "plugins"
