## 3. UserRepository (`user_repository.py`)

Handles **only** persistence. Uses parameterized queries (fixes the SQL injection bug).

```python
from typing import Optional, Protocol, List
from models import User, UserRole
from exceptions import DatabaseError, UserNotFoundError


class DatabaseConnection(Protocol):
    """Protocol so we can inject real or fake DBs."""
    def execute(self, query: str, params: tuple = ()) -> None: ...
    def fetch_one(self, query: str, params: tuple = ()) -> Optional[dict]: ...
    def fetch_all(self, query: str, params: tuple = ()) -> List[dict]: ...


class UserRepository:
    def __init__(self, db_conn: DatabaseConnection) -> None:
        self._db = db_conn

    def save(self, user: User) -> User:
        try:
            self._db.execute(
                "INSERT INTO users (id, name, email, role, active) VALUES (?, ?, ?, ?, ?)",
                (user.id, user.name, user.email, user.role.value, int(user.active)),
            )
        except Exception as exc:
            raise DatabaseError(f"Failed to save user {user.id}") from exc
        return user

    def mark_inactive(self, user_id: int) -> None:
        try:
            self._db.execute(
                "UPDATE users SET active = 0 WHERE id = ?",
                (user_id,),
            )
        except Exception as exc:
            raise DatabaseError(f"Failed to deactivate user {user_id}") from exc

    def find_by_id(self, user_id: int) -> Optional[User]:
        try:
            row = self._db.fetch_one(
                "SELECT id, name, email, role, active FROM users WHERE id = ?",
                (user_id,),
            )
        except Exception as exc:
            raise DatabaseError(f"Failed to fetch user {user_id}") from exc

        if row is None:
            return None
        return User(
            id=row["id"],
            name=row["name"],
            email=row["email"],
            role=UserRole(row["role"]),
            active=bool(row["active"]),
        )

    def exists(self, email: str) -> bool:
        try:
            row = self._db.fetch_one(
                "SELECT 1 FROM users WHERE email = ?",
                (email,),
            )
        except Exception as exc:
            raise DatabaseError("Existence check failed") from exc
        return row is not None
```

## 4. EmailService (`email_service.py`)

Handles **only** queuing and dispatching emails.

```python
from typing import List, Protocol
from dataclasses import dataclass


class EmailTransport(Protocol):
    """Protocol so we can inject a real SMTP client or a fake."""
    def send(self, to: str, subject: str, body: str) -> None: ...


@dataclass
class EmailMessage:
    to: str
    subject: str
    body: str


class EmailService:
    def __init__(self, transport: EmailTransport) -> None:
        self._queue: List[EmailMessage] = []
        self._transport = transport

    def enqueue(self, message: EmailMessage) -> None:
        self._queue.append(message)

    def flush(self) -> int:
        """Send every queued email. Returns count sent."""
        sent = 0
        for msg in list(self._queue):
            try:
                self._transport.send(msg.to, msg.subject, msg.body)
                sent += 1
            except Exception:
                # keep the message in the queue for retry
                continue
        # only clear the messages that were successfully sent
        self._queue = self._queue[sent:]
        return sent

    def pending_count(self) -> int:
        return len(self._queue)
```

