```python
import re
from models import UserRole
from exceptions import UserValidationError

_EMAIL_RE = re.compile(r"^[^@\s]+@[^@\s]+\.[^@\s]+$")


class UserValidator:
    def validate_name(self, name: str) -> None:
        if not isinstance(name, str) or not name.strip():
            raise UserValidationError("name", "must be a non-empty string")

    def validate_email(self, email: str) -> None:
        if not isinstance(email, str) or not _EMAIL_RE.match(email):
            raise UserValidationError("email", f"'{email}' is not a valid email")

    def validate_role(self, role: UserRole) -> None:
        if not isinstance(role, UserRole):
            raise UserValidationError("role", f"must be a UserRole, got {type(role).__name__}")

    def validate_new_user(self, name: str, email: str, role: UserRole) -> None:
        self.validate_name(name)
        self.validate_email(email)
        self.validate_role(role)
