## 7. UserService Facade (`user_service.py`)

Coordinates the components. **No business logic of its own** — pure orchestration.

```python
from typing import Optional
from models import User, UserRole
from user_repository import UserRepository
from email_service import EmailService, EmailMessage
from audit_service import AuditService
from user_validator import UserValidator
from exceptions import UserNotFoundError, DuplicateUserError


class UserService:
    def __init__(
        self,
        repository: UserRepository,
        email_service: EmailService,
        audit_service: AuditService,
        validator: UserValidator,
    ) -> None:
        self._repo = repository
        self._emails = email_service
        self._audit = audit_service
        self._validator = validator

    def create_user(self, name: str, email: str, role: UserRole) -> User:
        self._validator.validate_new_user(name, email, role)

        if self._repo.exists(email):
            raise DuplicateUserError(f"User with email {email!r} already exists")

        new_id = self._next_id()
        user = User(id=new_id, name=name, email=email, role=role, active=True)
        self._repo.save(user)

        self._emails.enqueue(EmailMessage(
            to=email,
            subject="Welcome",
            body=f"Hi {name}",
        ))
        self._audit.record("USER_CREATED", f"User {name!r} created with role {role.value}")
        return user

    def delete_user(self, user_id: int) -> User:
        user = self._repo.find_by_id(user_id)
        if user is None:
            raise UserNotFoundError(f"No user with id {user_id}")
        if not user.active:
            return user  # idempotent

        self._repo.mark_inactive(user_id)
        user.active = False

        self._emails.enqueue(EmailMessage(
            to=user.email,
            subject="Account Deleted",
            body="Your account has been deleted",
        ))
        self._audit.record("USER_DELETED", f"User {user.name!r} deleted")
        return user

    def get_user(self, user_id: int) -> User:
        user = self._repo.find_by_id(user_id)
        if user is None:
            raise UserNotFoundError(f"No user with id {user_id}")
        return user

    def send_pending_emails(self) -> int:
        return self._emails.flush()

    def get_audit_log(self):
        return self._audit.get_entries()

    def _next_id(self) -> int:
        # In a real system, the DB would assign IDs.
        # For this refactor we keep an internal counter.
        # (The original used len(self.users)+1, which is equally fragile —
        # flagged here for a future migration to autoincrement / UUID.)
        from itertools import count
        if not hasattr(self, "_id_counter"):
            self._id_counter = count(start=1)
        return next(self._id_counter)
```

