## Summary of Improvements

| Concern | Original | Refactored |
|---|---|---|
| **SQL injection** | f-string concatenation ❌ | Parameterized queries ✅ |
| **Responsibilities** | 1 god class | 5 focused classes |
| **Type safety** | Untyped dicts | `dataclass` + enums + hints |
| **Errors** | `return False` magic values | Custom exception hierarchy |
| **Testability** | `print()` + global state | DI via `Protocol`s + fakes |
| **Email retry** | Drops failures silently | Preserves failed messages |
| **Audit timestamps** | None | ISO-8601 UTC |
| **Idempotency** | Not handled | `delete_user` is safe to repeat |

Below is a complete, production‑oriented plugin architecture in a single Python module. It implements all eight requirements:

- **Plugin** base class with `on_load`, `on_unload`, `on_enable`, `on_disable`
- **PluginManager** that discovers plugin directories containing `plugin.toml`
- **Hot‑reload** with dependency aware disable→reload→re‑enable
- **Dependency declaration** + topological ordering + version compatibility via `packaging`
- **Plugin isolation** via exception‑safe wrappers around every lifecycle call and async event dispatch
- **TOML configuration** in each plugin’s manifest
- **EventBus** with per‑plugin subscription tracking so reloads don’t leak stale listeners

**Requires:** `packaging` (`pip install packaging`). TOML is read with `tomllib` (Python 3.11+) or `tomli` fallback.

---

### `plugin_system.py`

```python
from __future__ import annotations

import abc
import importlib.util
import logging
import sys
import threading
from concurrent.futures import ThreadPoolExecutor
from dataclasses import dataclass, field
from enum import Enum, auto
from pathlib import Path
from typing import Any, Callable, Dict, List, Optional, Set, Tuple

# --------------------------------------------------------------------------- #
# TOML parser (Python 3.11+ has tomllib built-in)
# --------------------------------------------------------------------------- #
try:
    import tomllib
except ImportError:
    try:
        import tomli as tomllib
    except ImportError:
        raise ImportError(
            "TOML parsing requires either Python 3.11+ or the 'tomli' package."
        ) from None

# --------------------------------------------------------------------------- #
# Packaging (pip install packaging)
# --------------------------------------------------------------------------- #
from packaging.specifiers import SpecifierSet
from packaging.version import Version

# =========================================================================== #
# Exceptions
# =========================================================================== #
class PluginError(Exception):
    """Base exception for the plugin system."""


class PluginLoadError(PluginError):
    """Raised when a plugin fails to load or reload."""


class PluginStateError(PluginError):
    """Raised when an invalid lifecycle transition is requested."""


class DependencyError(PluginError):
    """Raised when dependency constraints are violated."""


# =========================================================================== #
# Plugin State
# =========================================================================== #
class PluginState(Enum):
    UNLOADED = auto()
    LOADED = auto()
    ENABLED = auto()
    DISABLED = auto()


# =========================================================================== #
# Data Structures
# =========================================================================== #
@dataclass
class PluginMetadata:
    """Manifest describing a plugin, usually read from plugin.toml."""
    name: str
    version: str
    entry_point: str          # e.g. "Plugin" or "main.Plugin"
    module_path: str          # filesystem path to the plugin directory
    dependencies: Dict[str, str] = field(default_factory=dict)  # name -> version specifier
    config: Dict[str, Any] = field(default_factory=dict)


# =========================================================================== #
# Event Bus
# =========================================================================== #
class EventBus:
    """Central asynchronous pub/sub channel."""

    def __init__(self, max_workers: int = 10):
        self._subscribers: Dict[str, List[Callable]] = {}
        self._lock = threading.RLock()
        self._logger = logging.getLogger("EventBus")
        self._executor = ThreadPoolExecutor(
            max_workers=max_workers, thread_name_prefix="evt_"
        )

    # ---- subscription mgmt ------------------------------------------------ #
    def subscribe(self, event_type: str, handler: Callable) -> None:
        with self._lock:
            self._subscribers.setdefault(event_type, []).append(handler)

    def unsubscribe(self, event_type: str, handler: Callable) -> None:
        with self._lock:
            if event_type in self._subscribers:
                try:
                    self._subscribers[event_type].remove(handler)
                except ValueError:
                    pass

    # ---- publish ---------------------------------------------------------- #
    def publish(self, event_type: str, payload: Any = None) -> None:
        """Publish is async; each handler runs in the thread pool."""
        with self._lock:
            handlers = list(self._subscribers.get(event_type, []))
        for handler in handlers:
            self._executor.submit(self._dispatch, handler, event_type, payload)

    def _dispatch(self, handler: Callable, event_type: str, payload: Any) -> None:
        """Isolated invocation so one bad handler cannot kill others."""
        try:
            handler(event_type, payload)
        except Exception:
            self._logger.exception(
                "Handler %s crashed while processing '%s'", handler, event_type
            )

    def shutdown(self, wait: bool = True) -> None:
        self._executor.shutdown(wait=wait)


# =========================================================================== #
# Plugin Event Proxy (tracks a single plugin's listeners for clean teardown)
# =========================================================================== #
class PluginEventProxy:
    """Wraps EventBus so we can auto-unsubscribe on unload."""

    def __init__(self, event_bus: EventBus):
        self._event_bus = event_bus
        self._handlers: List[Tuple[str, Callable]] = []

    def subscribe(self, event_type: str, handler: Callable) -> None:
        self._event_bus.subscribe(event_type, handler)
        self._handlers.append((event_type, handler))

    def publish(self, event_type: str, payload: Any = None) -> None:
        self._event_bus.publish(event_type, payload)

    def unsubscribe_all(self) -> None:
        for event_type, handler in self._handlers:
            self._event_bus.unsubscribe(event_type, handler)
        self._handlers.clear()


# =========================================================================== #
# Plugin Context (injected into every plugin)
# =========================================================================== #
class PluginContext:
    def __init__(
        self,
        metadata: PluginMetadata,
        config: Dict[str, Any],
        event_proxy: PluginEventProxy,
        logger: logging.Logger,
    ):
        self.metadata = metadata
        self.config = config
        self.event_bus = event_proxy  # exposed under the familiar name
        self.logger = logger


# =========================================================================== #
# Plugin Base Class
# =========================================================================== #
class Plugin(abc.ABC):
    """Inherit from this to create a plugin."""

    def __init__(self):
        self.context: Optional[PluginContext] = None

    def set_context(self, context: PluginContext) -> None:
        self.context = context

    # ---- lifecycle hooks -------------------------------------------------- #
    def on_load(self) -> None:
        """Called once after the plugin class is instantiated."""

    def on_unload(self) -> None:
        """Called once before the plugin is removed from memory."""

    def on_enable(self) -> None:
        """Called when the plugin is activated (e.g. start threads)."""

    def on_disable(self) -> None:
        """Called when the plugin is deactivated (e.g. stop threads)."""

    # ---- convenience helpers ---------------------------------------------- #
    def emit(self, event_type: str, payload: Any = None) -> None:
        """Publish an event to the global bus."""
        if self.context:
            self.context.event_bus.publish(event_type, payload)

    def on(self, event_type: str, handler: Callable) -> None:
        """Subscribe to an event type."""
        if self.context:
            self.context.event_bus.subscribe(event_type, handler)


# =========================================================================== #
# Plugin Instance (internal wrapper that manages one loaded plugin)
# =========================================================================== #
class PluginInstance:
    """Lifecycle state machine around a single Plugin object."""

    def __init__(self, metadata: PluginMetadata, manager: PluginManager):
        self.metadata = metadata
        self.manager = manager
        self.state = PluginState.UNLOADED
        self.plugin: Optional[Plugin] = None
        self.module = None
        self._event_proxy: Optional[PluginEventProxy] = None
        self._logger = logging.getLogger(f"Plugin.{metadata.name}")
        self._lock = threading.Lock()

    # ---- module loading --------------------------------------------------- #
    def load(self) -> None:
        with self._lock:
            if self.state != PluginState.UNLOADED:
                return

            try:
                module_file, module_name = self._resolve_module_file()
                spec = importlib.util.spec_from_file_location(module_name, module_file)
                if spec is None or spec.loader is None:
                    raise PluginLoadError(
                        f"Cannot create module spec for {self.metadata.name}"
                    )

                module = importlib.util.module_from_spec(spec)
                # register in sys.modules so imports within the plugin resolve
                sys.modules[module_name] = module
                spec.loader.exec_module(module)
                self.module = module

                # instantiate the plugin class
                class_name = self.metadata.entry_point.split(".")[-1]
                cls = getattr(module, class_name)
                if not issubclass(cls, Plugin):
                    raise PluginLoadError(
                        f"{cls.__name__} must inherit from Plugin"
                    )

                self.plugin = cls()
                self._event_proxy = PluginEventProxy(self.manager.event_bus)
                ctx = PluginContext(
                    metadata=self.metadata,
                    config=self.metadata.config,
                    event_proxy=self._event_proxy,
                    logger=self._logger,
                )
                self.plugin.set_context(ctx)

                if not self._safe_call("on_load"):
                    raise PluginLoadError("on_load raised an exception")

                self.state = PluginState.LOADED
                self._logger.info("Loaded successfully")

            except Exception as exc:
                self._logger.exception("Load failed")
                self._cleanup()
                raise PluginLoadError(
                    f"Failed to load {self.metadata.name}: {exc}"
                ) from exc

    def _resolve_module_file(self) -> Tuple[Path, str]:
        """Return (file_path, dynamic_module_name) for importlib."""
        parts = self.metadata.entry_point.split(".")
        if len(parts) == 1:
            # class lives in the package's __init__.py
            file_path = Path(self.metadata.module_path) / "__init__.py"
            module_name = f"dynamic_plugin_{self.metadata.name}"
        else:
            # file_name.ClassName
            file_name = parts[0]
            file_path = Path(self.metadata.module_path) / f"{file_name}.py"
            module_name = f"dynamic_plugin_{self.metadata.name}.{file_name}"

        if not file_path.exists():
            raise PluginLoadError(f"Module file not found: {file_path}")

        return file_path, module_name

    # ---- lifecycle transitions -------------------------------------------- #
    def enable(self) -> None:
        with self._lock:
            if self.state == PluginState.ENABLED:
                return
            if self.state not in (PluginState.LOADED, PluginState.DISABLED):
                raise PluginStateError(
                    "Plugin must be loaded or disabled before enable"
                )
            if self._safe_call("on_enable"):
                self.state = PluginState.ENABLED
                self._logger.info("Enabled")
            else:
                self._logger.error("Enable failed (on_enable raised)")

    def disable(self) -> None:
        with self._lock:
            if self.state == PluginState.DISABLED:
                return
            if self.state != PluginState.ENABLED:
                raise PluginStateError("Plugin must be enabled before disable")
            self._safe_call("on_disable")
            self.state = PluginState.DISABLED
            self._logger.info("Disabled")

    def unload(self) -> None:
        with self._lock:
            if self.state == PluginState.UNLOADED:
                return
            if self.state == PluginState.ENABLED:
                self.disable()
            self._safe_call("on_unload")
            self._cleanup()
            self.state = PluginState.UNLOADED
            self._logger.info("Unloaded")

    def reload(self) -> None:
        """Hot reload: unload, refresh metadata from disk, load, re-enable."""
        with self._lock:
            was_enabled = self.state == PluginState.ENABLED
            self.unload()
            self._refresh_metadata()
            self.load()
            if was_enabled:
                self.enable()

    def _refresh_metadata(self) -> None:
        """Re-read plugin.toml so config / version changes are picked up."""
        toml_path = Path(self.metadata.module_path) / "plugin.toml"
        if not toml_path.exists():
            return
        try:
            with open(toml_path, "rb") as f:
                data = tomllib.load(f)
            plugin_section = data.get("plugin", {})
            self.metadata.version = plugin_section.get("version", self.metadata.version)
            self.metadata.dependencies = data.get("dependencies", self.metadata.dependencies)
            self.metadata.config = data.get("config", self.metadata.config)
        except Exception as exc:
            self._logger.warning("Failed to refresh metadata: %s", exc)

    # ---- safe isolation wrapper ------------------------------------------- #
    def _safe_call(self, method_name: str) -> bool:
        """Call a lifecycle hook, swallowing exceptions so the system stays up."""
        if not self.plugin:
            return False
        try:
            method = getattr(self.plugin, method_name, None)
            if callable(method):
                method()
            return True
        except Exception:
            self._logger.exception("Error during %s", method_name)
            return False

    # ---- cleanup ---------------------------------------------------------- #
    def _cleanup(self) -> None:
        """Remove module cache and listeners."""
        if self._event_proxy:
            self._event_proxy.unsubscribe_all()

        prefix = f"dynamic_plugin_{self.metadata.name}"
        to_remove = [
            k for k in sys.modules
            if k == prefix or k.startswith(prefix + ".")
        ]
        for key in to_remove:
            del sys.modules[key]

        self.module = None
        self.plugin = None
        self._event_proxy = None


# =========================================================================== #
# Plugin Manager
# =========================================================================== #
class PluginManager:
    """Discovers, loads, enables, and hot-reloads plugins."""

    def __init__(self, plugin_directory: str):
        self.plugin_directory = Path(plugin_directory)
        self._metadata: Dict[str, PluginMetadata] = {}
        self._plugins: Dict[str, PluginInstance] = {}
        self.event_bus = EventBus()
        self._logger = logging.getLogger("PluginManager")
        self._lock = threading.RLock()

    # ---- discovery -------------------------------------------------------- #
    def discover(self) -> None:
        """Scan plugin_directory for subdirectories containing plugin.toml."""
        self._metadata.clear()
        if not self.plugin_directory.exists():
            self._logger.warning("Plugin directory does not exist: %s", self.plugin_directory)
            return

        for path in self.plugin_directory.iterdir():
            if not path.is_dir():
                continue
            toml_file = path / "plugin.toml"
            if not toml_file.exists():
                continue

            try:
                with open(toml_file, "rb") as f:
                    data = tomllib.load(f)

                plugin_section = data.get("plugin", {})
                name = plugin_section.get("name")
                if not name:
                    self._logger.warning("Skipping %s: missing plugin.name", toml_file)
                    continue

                self._metadata[name] = PluginMetadata(
                    name=name,
                    version=plugin_section.get("version", "0.0.0"),
                    entry_point=plugin_section.get("entry_point", "Plugin"),
                    module_path=str(path),
                    dependencies=data.get("dependencies", {}),
                    config=data.get("config", {}),
                )
            except Exception as exc:
                self._logger.error("Failed to discover %s: %s", toml_file, exc)

    # ---- loading ---------------------------------------------------------- #
    def load(self, name: str) -> None:
        with self._lock:
            if name in self._plugins:
                return
            if name not in self._metadata:
                raise PluginLoadError(f"Unknown plugin: {name}")

            metadata = self._metadata[name]
            self._check_dependencies(metadata)

            instance = PluginInstance(metadata, self)
            instance.load()
            self._plugins[name] = instance

    def load_all(self) -> None:
        """Load all discovered plugins in dependency order."""
        graph = {
            name: set(meta.dependencies.keys())
            for name, meta in self._metadata.items()
        }
        order = self._topological_visit(graph)
        for name in order:
            try:
                self.load(name)
            except PluginError as exc:
                self._logger.error("Failed to load %s: %s", name, exc)

    def _check_dependencies(self, metadata: PluginMetadata) -> None:
        """Ensure declared dependencies are present and version-compatible."""
        for dep_name, version_spec in metadata.dependencies.items():
            if dep_name not in self._plugins:
                raise DependencyError(
                    f"{metadata.name} requires {dep_name}, but it is not loaded"
                )

            dep = self._plugins[dep_name]
            if dep.state == PluginState.UNLOADED:
                raise DependencyError(
                    f"{metadata.name} requires {dep_name}, but it is unloaded"
                )

            if version_spec:
                try:
                    dep_version = Version(dep.metadata.version)
                    spec = SpecifierSet(version_spec)
                    if dep_version not in spec:
                        raise DependencyError(
                            f"{metadata.name} requires {dep_name}{version_spec}, "
                            f"but found {dep.metadata.version}"
                        )
                except Exception as exc:
                    raise DependencyError(
                        f"Invalid version spec for {dep_name}: {exc}"
                    ) from exc

    # ---- unloading -------------------------------------------------------- #
    def unload(self, name: str) -> None:
        with self._lock:
            if name not in self._plugins:
                return

            # Prevent unload if other loaded plugins depend on this one
            dependents = self._get_dependents(name)
            loaded_dependents = [
                d for d in dependents
                if self._plugins[d].state != PluginState.UNLOADED
            ]
            if loaded_dependents:
                raise DependencyError(
                    f"Cannot unload {name}, loaded dependents exist: {loaded_dependents}"
                )

            self._plugins[name].unload()
            del self._plugins[name]

    def unload_all(self) -> None:
        for name in list(self._plugins.keys()):
            try:
                self.unload(name)
            except PluginError as exc:
                self._logger.error("Failed to unload %s: %s", name, exc)

    # ---- enable / disable ------------------------------------------------- #
    def enable(self, name: str) -> None:
        with self._lock:
            if name not in self._plugins:
                raise PluginStateError(f"Plugin {name} is not loaded")
            self._plugins[name].enable()

    def enable_all(self) -> None:
        for name in list(self._plugins.keys()):
            try:
                self.enable(name)
            except Exception as exc:
                self._logger.error("Failed to enable %s: %s", name, exc)

    def disable(self, name: str) -> None:
        with self._lock:
            if name not in self._plugins:
                raise PluginStateError(f"Plugin {name} is not loaded")
            self._plugins[name].disable()

    # ---- hot reload ------------------------------------------------------- #
    def reload(self, name: str) -> None:
        """Reload a single plugin at runtime. Dependents are temporarily disabled."""
        with self._lock:
            if name not in self._plugins:
                self.load(name)
                return

            instance = self._plugins[name]

            # Gracefully disable anything that depends on this plugin
            dependents = self._get_dependents(name)
            enabled_dependents = [
                d for d in dependents
                if self._plugins[d].state == PluginState.ENABLED
            ]
            for d in enabled_dependents:
                self._plugins[d].disable()

            instance.reload()

            # Bring dependents back up
            for d in enabled_dependents:
                self._plugins[d].enable()

    # ---- helpers ---------------------------------------------------------- #
    def get_plugin(self, name: str) -> Optional[PluginInstance]:
        return self._plugins.get(name)

    def _get_dependents(self, name: str) -> List[str]:
        """Return names of *loaded* plugins that declare a dependency on `name`."""
        return [
            n for n, m in self._metadata.items()
            if name in m.dependencies and n in self._plugins
        ]

    def _topological_visit(self, graph: Dict[str, Set[str]]) -> List[str]:
        """DFS that outputs dependencies before their consumers."""
        visited: Set[str] = set()
        result: List[str] = []

        def visit(node: str) -> None:
            if node in visited:
                return
            visited.add(node)
            for dep in graph.get(node, set()):
                if dep in self._metadata:
                    visit(dep)
            result.append(node)

        for node in list(graph.keys()):
            visit(node)
        return result

    def shutdown(self) -> None:
        """Disable and unload everything, then stop the event bus."""
        self.unload_all()
        self.event_bus.shutdown()
