"""Configuration management for the knowledge base CLI."""

import os
import shutil
from pathlib import Path
from typing import Any, Dict, Optional

import toml


DEFAULT_CONFIG = {
    "database": {"path": "~/.kb/knowledge.db"},
    "defaults": {"notebook": "default"},
    "export": {"output_dir": "~/.kb/exports"},
}


class Config:
    """Handle TOML configuration persistence and access."""

    def __init__(self, config_path: Optional[str] = None) -> None:
        self.config_path = Path(config_path or "~/.kb/config.toml").expanduser()
        self._config: Dict[str, Any] = {}
        self.load()

    def load(self) -> None:
        """Load config from disk or create with defaults."""
        if self.config_path.exists():
            with open(self.config_path, "r", encoding="utf-8") as f:
                self._config = toml.load(f)
        else:
            self._config = self._deep_copy(DEFAULT_CONFIG)
            self.save()

    def save(self) -> None:
        """Persist current config to disk."""
        self.config_path.parent.mkdir(parents=True, exist_ok=True)
        with open(self.config_path, "w", encoding="utf-8") as f:
            toml.dump(self._config, f)

    def get(self, key: str, default: Any = None) -> Any:
        """Dot-notation access, e.g. config.get('database.path')."""
        keys = key.split(".")
        value: Any = self._config
        for k in keys:
            if isinstance(value, dict) and k in value:
                value = value[k]
            else:
                return default
        return value

    def set(self, key: str, value: Any) -> None:
        """Dot-notation assignment, e.g. config.set('database.path', '...')."""
        keys = key.split(".")
        d = self._config
        for k in keys[:-1]:
            if k not in d or not isinstance(d[k], dict):
                d[k] = {}
            d = d[k]
        d[keys[-1]] = value
        self.save()

    @property
    def db_path(self) -> Path:
        return Path(self.get("database.path", "~/.kb/knowledge.db")).expanduser()

    @property
    def export_dir(self) -> Path:
        return Path(self.get("export.output_dir", "~/.kb/exports")).expanduser()

    @property
    def default_notebook(self) -> str:
        return self.get("defaults.notebook", "default")

    @staticmethod
    def _deep_copy(obj: Any) -> Any:
        """Simple deep copy for dict/list primitives."""
        if isinstance(obj, dict):
            return {k: Config._deep_copy(v) for k, v in obj.items()}
        if isinstance(obj, list):
            return [Config._deep_copy(v) for v in obj]
        return obj
