"""SQLite storage layer with FTS5 full-text search."""

import sqlite3
import uuid
from contextlib import contextmanager
from datetime import datetime
from pathlib import Path
from typing import Any, Dict, List, Optional

from .config import Config
from .models import Note, Notebook, Tag


SCHEMA = """
CREATE TABLE IF NOT EXISTS notebooks (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL UNIQUE,
    description TEXT,
    created_at TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS tags (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL UNIQUE,
    created_at TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS notes (
    id TEXT PRIMARY KEY,
    title TEXT NOT NULL,
    content TEXT NOT NULL,
    notebook_id TEXT REFERENCES notebooks(id),
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS note_tags (
    note_id TEXT REFERENCES notes(id) ON DELETE CASCADE,
    tag_id TEXT REFERENCES tags(id) ON DELETE CASCADE,
    PRIMARY KEY (note_id, tag_id)
);

CREATE VIRTUAL TABLE IF NOT EXISTS notes_fts USING fts5(
    title,
    content,
    content_rowid=rowid,
    content=notes
);

CREATE TRIGGER IF NOT EXISTS notes_ai AFTER INSERT ON notes BEGIN
    INSERT INTO notes_fts(rowid, title, content)
    VALUES (new.rowid, new.title, new.content);
END;

CREATE TRIGGER IF NOT EXISTS notes_ad AFTER DELETE ON notes BEGIN
    INSERT INTO notes_fts(notes_fts, rowid, title, content)
    VALUES('delete', old.rowid, old.title, old.content);
END;

CREATE TRIGGER IF NOT EXISTS notes_au AFTER UPDATE ON notes BEGIN
    INSERT INTO notes_fts(notes_fts, rowid, title, content)
    VALUES('delete', old.rowid, old.title, old.content);
    INSERT INTO notes_fts(rowid, title, content)
    VALUES (new.rowid, new.title, new.content);
END;
"""


class StorageError(Exception):
    pass


class Storage:
    """Production-grade SQLite storage with FTS5 support."""

    def __init__(self, config: Optional[Config] = None) -> None:
        self.config = config or Config()
        self.db_path = Path(self.config.db_path)
        self.db_path.parent.mkdir(parents=True, exist_ok=True)
        self._init_db()

    @contextmanager
    def _connect(self):
        conn = sqlite3.connect(
            str(self.db_path),
            detect_types=sqlite3.PARSE_DECLTYPES,
            timeout=10.0,
        )
        conn.row_factory = sqlite3.Row
        conn.execute("PRAGMA foreign_keys = ON")
        try:
            yield conn
            conn.commit()
        except Exception:
            conn.rollback()
            raise
        finally:
            conn.close()

    def _init_db(self) -> None:
        with self._connect() as conn:
            conn.executescript(SCHEMA)
            default = self.config.default_notebook
            conn.execute(
                """INSERT OR IGNORE INTO notebooks (id, name, description, created_at)
                   VALUES (?, ?, ?, ?)""",
                (default, default, "Default notebook", datetime.utcnow().isoformat()),
            )

    def add_notebook(self, notebook: Notebook) -> Notebook:
        with self._connect() as conn:
            try:
                conn.execute(
                    """INSERT INTO notebooks (id, name, description, created_at)
                       VALUES (?, ?, ?, ?)""",
                    (
                        notebook.id,
                        notebook.name,
                        notebook.description,
                        notebook.created_at.isoformat(),
                    ),
                )
            except sqlite3.IntegrityError as exc:
                raise StorageError(f"Notebook '{notebook.name}' already exists") from exc
        return notebook

    def get_notebook(self, notebook_id: str) -> Optional[Notebook]:
        with self._connect() as conn:
            row = conn.execute(
                "SELECT * FROM notebooks WHERE id = ?", (notebook_id,)
            ).fetchone()
            if not row:
                return None
            return self._row_to_notebook(row)

    def list_notebooks(self) -> List[Notebook]:
        with self._connect() as conn:
            rows = conn.execute("SELECT * FROM notebooks ORDER BY name").fetchall()
            return [self._row_to_notebook(r) for r in rows]

    def add_tag(self, tag: Tag) -> Tag:
        with self._connect() as conn:
            try:
                conn.execute(
                    "INSERT INTO tags (id, name, created_at) VALUES (?, ?, ?)",
                    (tag.id, tag.name, tag.created_at.isoformat()),
                )
            except sqlite3.IntegrityError:
                existing = conn.execute(
                    "SELECT * FROM tags WHERE name = ?", (tag.name,)
                ).fetchone()
                if existing:
                    return self._row_to_tag(existing)
                raise
        return tag

    def get_tag(self, tag_id: str) -> Optional[Tag]:
        with self._connect() as conn:
            row = conn.execute("SELECT * FROM tags WHERE id = ?", (tag_id,)).fetchone()
            return self._row_to_tag(row) if row else None

    def get_tag_by_name(self, name: str) -> Optional[Tag]:
        with self._connect() as conn:
            row = conn.execute(
                "SELECT * FROM tags WHERE name = ?", (name.lower(),)
            ).fetchone()
            return self._row_to_tag(row) if row else None

    def list_tags(self) -> List[Tag]:
        with self._connect() as conn:
            rows = conn.execute("SELECT * FROM tags ORDER BY name").fetchall()
            return [self._row_to_tag(r) for r in rows]

    def add_note(self, note: Note) -> Note:
        with self._connect() as conn:
            self._persist_note(conn, note, insert=True)
        return note

    def update_note(self, note: Note) -> Note:
        note.updated_at = datetime.utcnow()
        with self._connect() as conn:
            self._persist_note(conn, note, insert=False)
        return note

    def _persist_note(self, conn, note: Note, insert: bool) -> None:
        if insert:
            conn.execute(
                """INSERT INTO notes (id, title, content, notebook_id, created_at, updated_at)
                   VALUES (?, ?, ?, ?, ?, ?)""",
                (
                    note.id,
                    note.title,
                    note.content,
                    note.notebook_id,
                    note.created_at.isoformat(),
                    note.updated_at.isoformat(),
                ),
            )
        else:
            conn.execute(
                """UPDATE notes SET title=?, content=?, notebook_id=?, updated_at=?
                   WHERE id=?""",
                (
                    note.title,
                    note.content,
                    note.notebook_id,
                    note.updated_at.isoformat(),
                    note.id,
                ),
            )
            conn.execute("DELETE FROM note_tags WHERE note_id = ?", (note.id,))

        # Reconcile tags
        for tag_name in note.tags:
            tag_id = str(uuid.uuid4())
            try:
                conn.execute(
                    "INSERT INTO tags (id, name, created_at) VALUES (?, ?, ?)",
                    (tag_id, tag_name, datetime.utcnow().isoformat()),
                )
            except sqlite3.IntegrityError:
                existing = conn.execute(
                    "SELECT id FROM tags WHERE name = ?", (tag_name,)
                ).fetchone()
                tag_id = existing["id"]
            conn.execute(
                "INSERT OR IGNORE INTO note_tags (note_id, tag_id) VALUES (?, ?)",
                (note.id, tag_id),
            )

    def delete_note(self, note_id: str) -> None:
        with self._connect() as conn:
            conn.execute("DELETE FROM notes WHERE id = ?", (note_id,))

    def get_note(self, note_id: str) -> Optional[Note]:
        with self._connect() as conn:
            row = conn.execute("SELECT * FROM notes WHERE id = ?", (note_id,)).fetchone()
            if not row:
                return None
            return self._row_to_note(conn, row)

    def list_notes(
        self,
        notebook_id: Optional[str] = None,
        tag: Optional[str] = None,
        limit: int = 50,
        offset: int = 0,
    ) -> List[Note]:
        with self._connect() as conn:
            query = "SELECT * FROM notes WHERE 1=1"
            params: List[Any] = []

            if notebook_id:
                query += " AND notebook_id = ?"
                params.append(notebook_id)

            if tag:
                query += """ AND id IN (
                    SELECT nt.note_id FROM note_tags nt
                    JOIN tags t ON nt.tag_id = t.id WHERE t.name = ?
                )"""
                params.append(tag)

            query += " ORDER BY updated_at DESC LIMIT ? OFFSET ?"
            params.extend([limit, offset])

            rows = conn.execute(query, params).fetchall()
            return [self._row_to_note(conn, r) for r in rows]

    def search_notes(self, query: str, limit: int = 50) -> List[Dict[str, Any]]:
        with self._connect() as conn:
            try:
                rows = conn.execute(
                    """SELECT n.*, rank
                       FROM notes_fts
                       JOIN notes n ON notes_fts.rowid = n.rowid
                       WHERE notes_fts MATCH ?
                       ORDER BY rank
                       LIMIT ?""",
                    (query, limit),
                ).fetchall()
            except sqlite3.OperationalError:
                # Fallback if rank is unavailable for some reason
                rows = conn.execute(
                    """SELECT n.*, 0.0 AS rank
                       FROM notes_fts
                       JOIN notes n ON notes_fts.rowid = n.rowid
                       WHERE notes_fts MATCH ?
                       LIMIT ?""",
                    (query, limit),
                ).fetchall()

            return [
                {"note": self._row_to_note(conn, r), "rank": r["rank"]} for r in rows
            ]

    def get_stats(self) -> Dict[str, int]:
        with self._connect() as conn:
            notes = conn.execute("SELECT COUNT(*) AS c FROM notes").fetchone()["c"]
            tags = conn.execute("SELECT COUNT(*) AS c FROM tags").fetchone()["c"]
            notebooks = conn.execute("SELECT COUNT(*) AS c FROM notebooks").fetchone()["c"]
            return {"notes": notes, "tags": tags, "notebooks": notebooks}

    def _row_to_note(self, conn, row: sqlite3.Row) -> Note:
        tags = [
            r["name"]
            for r in conn.execute(
                """SELECT t.name FROM tags t
                   JOIN note_tags nt ON t.id = nt.tag_id
                   WHERE nt.note_id = ?""",
                (row["id"],),
            ).fetchall()
        ]
        return Note(
            id=row["id"],
            title=row["title"],
            content=row["content"],
            notebook_id=row["notebook_id"],
            tags=tags,
            created_at=datetime.fromisoformat(row["created_at"]),
            updated_at=datetime.fromisoformat(row["updated_at"]),
        )

    def _row_to_tag(self, row: sqlite3.Row) -> Tag:
        return Tag(
            id=row["id"],
            name=row["name"],
            created_at=datetime.fromisoformat(row["created_at"]),
        )

    def _row_to_notebook(self, row: sqlite3.Row) -> Notebook:
        return Notebook(
            id=row["id"],
            name=row["name"],
            description=row["description"] or "",
            created_at=datetime.fromisoformat(row["created_at"]),
        )
