"""Search engine with relevance scoring and query sanitization."""

import re
from typing import Any, Dict, List

from .models import Note
from .storage import Storage


class SearchEngine:
    """Wraps storage FTS5 and adds ranking heuristics."""

    def __init__(self, storage: Storage) -> None:
        self.storage = storage

    def search(self, query: str, limit: int = 50) -> List[Dict[str, Any]]:
        if not query or not query.strip():
            return []

        cleaned = self._sanitize_query(query)
        raw_results = self.storage.search_notes(cleaned, limit=limit)

        scored = []
        for item in raw_results:
            note: Note = item["note"]
            base_rank = item.get("rank", 0)

            if base_rank is None or base_rank == 0:
                score = self._calculate_score(note, query)
            else:
                # BM25 returns negative values; convert to positive score
                score = abs(1.0 / (float(base_rank) + 0.1))

            scored.append(
                {
                    "note": note,
                    "score": round(score, 4),
                }
            )

        return sorted(scored, key=lambda x: x["score"], reverse=True)

    @staticmethod
    def _sanitize_query(query: str) -> str:
        # Escape/sanitize for safe FTS5 tokenization
        # Remove characters that can break FTS5 syntax
        cleaned = re.sub(r'[^\w\s\-\"]', " ", query)
        return " ".join(cleaned.split())

    @staticmethod
    def _calculate_score(note: Note, query: str) -> float:
        q = query.lower()
        title = note.title.lower()
        content = note.content.lower()
        score = 0.0

        # Title matches
        if q in title:
            score += 10.0
            if title.startswith(q):
                score += 5.0

        # Content match
        if q in content:
            score += 1.0

        # Tag matches
        for tag in note.tags:
            if q in tag:
                score += 3.0

        # Word-level bonuses
        words = q.split()
        for word in words:
            if len(word) < 2:
                continue
            if word in title:
                score += 2.0
            if word in content:
                score += 0.5

        return score
