"""Export formats: Markdown, JSON, and HTML."""

import html as html_module
import json
import re
from datetime import datetime
from pathlib import Path
from typing import List

from .config import Config
from .models import Note
from .storage import Storage


class Exporter:
    def __init__(self, storage: Storage, config: Config) -> None:
        self.storage = storage
        self.config = config

    def export_markdown(self, notes: List[Note], output_path: str) -> Path:
        path = Path(output_path)
        lines: List[str] = []
        for note in notes:
            lines.append(f"# {note.title}\n")
            if note.tags:
                lines.append(f"**Tags:** {', '.join(note.tags)}\n")
            lines.append(
                f"*Created: {note.created_at.isoformat()} | "
                f"Updated: {note.updated_at.isoformat()}*\n"
            )
            lines.append(note.content)
            lines.append("\n---\n")
        path.write_text("\n".join(lines), encoding="utf-8")
        return path

    def export_json(self, notes: List[Note], output_path: str) -> Path:
        path = Path(output_path)
        payload = []
        for note in notes:
            payload.append(
                {
                    "id": note.id,
                    "title": note.title,
                    "content": note.content,
                    "tags": note.tags,
                    "notebook_id": note.notebook_id,
                    "created_at": note.created_at.isoformat(),
                    "updated_at": note.updated_at.isoformat(),
                }
            )
        path.write_text(json.dumps(payload, indent=2), encoding="utf-8")
        return path

    def export_html(self, notes: List[Note], output_path: str) -> Path:
        path = Path(output_path)
        parts = [
            "<!DOCTYPE html>",
            "<html><head>",
            "<meta charset='utf-8'>",
            "<title>Knowledge Base Export</title>",
            "<style>",
            "body{font-family:system-ui,sans-serif;max-width:800px;margin:2em auto;padding:0 1em;color:#333}",
            "h1{border-bottom:2px solid #eee;padding-bottom:.3em}",
            ".meta{color:#666;font-size:.9em;margin-bottom:1em}",
            ".tag{background:#f0f0f0;padding:.2em .5em;border-radius:3px;display:inline-block;margin-right:.5em}",
            "pre{background:#f6f6f6;padding:1em;overflow-x:auto}",
            "hr{border:none;border-top:1px solid #eee;margin:2em 0}",
            "</style></head><body>",
            f"<h1>Knowledge Base Export</h1><p>{datetime.utcnow().isoformat()} UTC</p>",
        ]

        for note in notes:
            parts.append(f"<h2>{html_module.escape(note.title)}</h2>")
            meta = []
            if note.tags:
                tags_html = "".join(
                    f'<span class="tag">{html_module.escape(t)}</span>' for t in note.tags
                )
                meta.append(f"<div>Tags: {tags_html}</div>")
            meta.append(
                f"<div class='meta'>Created: {note.created_at.isoformat()} | "
                f"Updated: {note.updated_at.isoformat()}</div>"
            )
            parts.extend(meta)
            parts.append(f"<div>{self._markdown_to_html(note.content)}</div>")
            parts.append("<hr>")

        parts.append("</body></html>")
        path.write_text("\n".join(parts), encoding="utf-8")
        return path

    @staticmethod
    def _markdown_to_html(text: str) -> str:
        """Basic markdown-to-HTML conversion for export."""
        lines = text.split("\n")
        out: List[str] = []
        in_pre = False

        for line in lines:
            if line.startswith("```"):
                if in_pre:
                    out.append("</pre>")
                    in_pre = False
                else:
                    out.append("<pre>")
                    in_pre = True
                continue

            if in_pre:
                out.append(html_module.escape(line))
                continue

            line = html_module.escape(line)

            # Bold / italic
            line = re.sub(r"\*\*(.+?)\*\*", r"<strong>\1</strong>", line)
            line = re.sub(r"\*(.+?)\*", r"<em>\1</em>", line)

            # Headers
            if line.startswith("# "):
                line = f"<h3>{line[2:]}</h3>"
            elif line.startswith("## "):
                line = f"<h4>{line[3:]}</h4>"
            elif line.startswith("- "):
                line = f"<li>{line[2:]}</li>"
            elif line.strip() == "":
                line = ""
            else:
                line = f"<p>{line}</p>"

            out.append(line)

        return "\n".join(out)
