"""Main CLI entrypoint using Click."""

import uuid
from datetime import datetime
from pathlib import Path

import click

from .config import Config
from .export import Exporter
from .models import Note, Notebook
from .search import SearchEngine
from .storage import Storage, StorageError


@click.group()
@click.option(
    "--config",
    "config_path",
    type=click.Path(),
    default=None,
    help="Path to TOML config file.",
)
@click.pass_context
def cli(ctx, config_path):
    """Personal Knowledge Base CLI.

    Manage notes, notebooks, and tags with full-text search and export.
    """
    config = Config(config_path)
    storage = Storage(config)
    ctx.ensure_object(dict)
    ctx.obj["config"] = config
    ctx.obj["storage"] = storage
    ctx.obj["search"] = SearchEngine(storage)
    ctx.obj["exporter"] = Exporter(storage, config)


def _get_storage(ctx) -> Storage:
    return ctx.obj["storage"]


def _get_search(ctx) -> SearchEngine:
    return ctx.obj["search"]


def _get_exporter(ctx) -> Exporter:
    return ctx.obj["exporter"]


@cli.command()
@click.argument("title")
@click.option("--content", "-c", default="", help="Note content as a string.")
@click.option(
    "--file",
    "-f",
    type=click.File("r"),
    help="Read note content from a file.",
)
@click.option("--notebook", "-n", default=None, help="Target notebook ID or name.")
@click.option("--tag", "-t", multiple=True, help="Attach tags (repeatable).")
@click.pass_context
def add(ctx, title, content, file, notebook, tag):
    """Add a new note to the knowledge base."""
    storage = _get_storage(ctx)

    if file:
        content = file.read()

    if not content:
        content = click.edit() or ""

    if not content or not content.strip():
        raise click.UsageError("Content cannot be empty.")

    nb_id = notebook or storage.config.default_notebook
    if not storage.get_notebook(nb_id):
        nb = Notebook(id=nb_id, name=nb_id)
        try:
            storage.add_notebook(nb)
        except StorageError:
            pass

    note = Note(
        title=title,
        content=content,
        notebook_id=nb_id,
        tags=list(tag),
    )
    storage.add_note(note)
    click.echo(f"Created note {click.style(note.id, fg='cyan')}")


@cli.command()
@click.argument("query")
@click.option("--limit", "-l", default=20, help="Maximum number of results.")
@click.pass_context
def search(ctx, query, limit):
    """Full-text search across notes with relevance scoring."""
    engine = _get_search(ctx)
    results = engine.search(query, limit=limit)

    if not results:
        click.echo("No results found.")
        return

    for res in results:
        note = res["note"]
        click.echo()
        click.echo(
            click.style(f"[{note.id}]", fg="cyan", dim=True)
            + " "
            + click.style(note.title, bold=True)
        )
        click.echo(f"  Score: {res['score']}")
        if note.tags:
            click.echo(
                click.style(f"  Tags: {', '.join(note.tags)}", fg="yellow")
            )
        preview = note.content.replace("\n", " ")[:200]
        if len(note.content) > 200:
            preview += "..."
        click.echo(f"  {preview}")


@cli.command("list")
@click.option("--notebook", "-n", help="Filter by notebook ID.")
@click.option("--tag", "-t", help="Filter by tag name.")
@click.option("--limit", "-l", default=50, help="Limit results.")
@click.option("--offset", "-o", default=0, help="Offset results.")
@click.pass_context
def list_cmd(ctx, notebook, tag, limit, offset):
    """List notes with optional filtering."""
    storage = _get_storage(ctx)
    notes = storage.list_notes(
        notebook_id=notebook, tag=tag, limit=limit, offset=offset
    )

    if not notes:
        click.echo("No notes found.")
        return

    for note in notes:
        date = note.updated_at.strftime("%Y-%m-%d")
        click.echo(
            click.style(f"[{note.id}]", fg="cyan", dim=True)
            + " "
            + click.style(note.title, bold=True)
            + click.style(f" ({date})", fg="green")
        )
        if note.tags:
            click.echo(f"  tags: {', '.join(note.tags)}")


@cli.command()
@click.argument("note_id")
@click.option("--yes", is_flag=True, help="Skip confirmation prompt.")
@click.pass_context
def delete(ctx, note_id, yes):
    """Delete a note by ID."""
    storage = _get_storage(ctx)
    note = storage.get_note(note_id)
    if not note:
        raise click.UsageError(f"Note '{note_id}' not found.")

    if not yes:
        if not click.confirm(f"Delete '{note.title}'?"):
            click.echo("Cancelled.")
            return

    storage.delete_note(note_id)
    click.echo("Note deleted.")


@cli.command("export")
@click.option(
    "--format",
    "fmt",
    type=click.Choice(["md", "json", "html"]),
    default="md",
    help="Export format.",
)
@click.option("--output", "-o", required=True, help="Output file path.")
@click.option("--notebook", "-n", help="Export only a specific notebook.")
@click.option("--tag", "-t", help="Export only notes with a specific tag.")
@click.pass_context
def export_cmd(ctx, fmt, output, notebook, tag):
    """Export notes to Markdown, JSON, or HTML."""
    storage = _get_storage(ctx)
    exporter = _get_exporter(ctx)

    notes = storage.list_notes(notebook_id=notebook, tag=tag, limit=100000)
    if not notes:
        click.echo("No notes match the given criteria.")
        return

    out_path = Path(output)
    out_path.parent.mkdir(parents=True, exist_ok=True)

    if fmt == "md":
        exporter.export_markdown(notes, output)
    elif fmt == "json":
        exporter.export_json(notes, output)
    elif fmt == "html":
        exporter.export_html(notes, output)

    click.echo(f"Exported {len(notes)} notes to {click.style(output, fg='green')}")


@cli.group()
def tag():
    """Tag management commands."""
    pass


@tag.command("add")
@click.argument("note_id")
@click.argument("tag_name")
@click.pass_context
def tag_add(ctx, note_id, tag_name):
    """Add a tag to a note."""
    storage = _get_storage(ctx)
    note = storage.get_note(note_id)
    if not note:
        raise click.UsageError(f"Note '{note_id}' not found.")

    if tag_name.lower() not in note.tags:
        note.tags.append(tag_name.lower())
        storage.update_note(note)
        click.echo(f"Added tag '{tag_name}' to note.")
    else:
        click.echo("Tag already exists on note.")


@tag.command("remove")
@click.argument("note_id")
@click.argument("tag_name")
@click.pass_context
def tag_remove(ctx, note_id, tag_name):
    """Remove a tag from a note."""
    storage = _get_storage(ctx)
    note = storage.get_note(note_id)
    if not note:
        raise click.UsageError(f"Note '{note_id}' not found.")

    t = tag_name.lower()
    if t in note.tags:
        note.tags.remove(t)
        storage.update_note(note)
        click.echo(f"Removed tag '{tag_name}' from note.")
    else:
        click.echo("Tag not found on note.")


@tag.command("list")
@click.pass_context
def tag_list(ctx):
    """List all tags in the knowledge base."""
    storage = _get_storage(ctx)
    tags = storage.list_tags()
    if not tags:
        click.echo("No tags found.")
        return
    for t in tags:
        click.echo(t.name)


@cli.command()
@click.pass_context
def stats(ctx):
    """Show knowledge base statistics."""
    storage = _get_storage(ctx)
    data = storage.get_stats()
    click.echo(f"Notes:     {data['notes']}")
    click.echo(f"Tags:      {data['tags']}")
    click.echo(f"Notebooks: {data['notebooks']}")


def main():
    cli()


if __name__ == "__main__":
    main()
